window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["刑法"] = {"xingfa":[{"i":1,"n":"第一条","txt":"为了惩罚犯罪，保护人民，根据宪法，结合我国同犯罪作斗争的具体经验及实际情况，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国刑法的任务，是用刑罚同一切犯罪行为作斗争，以保卫国家安全，保卫人民民主专政的政权和社会主义制度，保护国有财产和劳动群众集体所有的财产，保护公民私人所有的财产，保护公民的人身权利、民主权利和其他权利，维护社会秩序、经济秩序，保障社会主义建设事业的顺利进行。"},{"i":3,"n":"第三条","txt":"法律明文规定为犯罪行为的，依照法律定罪处刑；法律没有明文规定为犯罪行为的，不得定罪处刑。"},{"i":4,"n":"第四条","txt":"对任何人犯罪，在适用法律上一律平等。不允许任何人有超越法律的特权。"},{"i":5,"n":"第五条","txt":"刑罚的轻重，应当与犯罪分子所犯罪行和承担的刑事责任相适应。"},{"i":6,"n":"第六条","txt":"凡在中华人民共和国领域内犯罪的，除法律有特别规定的以外，都适用本法。"},{"i":7,"n":"第七条","txt":"中华人民共和国公民在中华人民共和国领域外犯本法规定之罪的，适用本法，但是按本法规定的最高刑为三年以下有期徒刑的，可以不予追究。"},{"i":8,"n":"第八条","txt":"外国人在中华人民共和国领域外对中华人民共和国国家或者公民犯罪，而按本法规定的最低刑为三年以上有期徒刑的，可以适用本法，但是按照犯罪地的法律不受处罚的除外。"},{"i":9,"n":"第九条","txt":"对于中华人民共和国缔结或者参加的国际条约所规定的罪行，中华人民共和国在所承担条约义务的范围内行使刑事管辖权的，适用本法。"},{"i":10,"n":"第十条","txt":"凡在中华人民共和国领域外犯罪，依照本法应当负刑事责任的，虽然经过外国审判，仍然可以依照本法追究，但是在外国已经受过刑罚处罚的，可以免除或者减轻处罚。"},{"i":11,"n":"第十一条","txt":"享有外交特权和豁免权的外国人的刑事责任，通过外交途径解决。"},{"i":12,"n":"第十二条","txt":"中华人民共和国成立以后本法施行以前的行为，如果当时的法律不认为是犯罪的，适用当时的法律；如果当时的法律认为是犯罪的，依照本法总则第四章第八节的规定应当追诉的，按照当时的法律追究刑事责任，但是如果本法不认为是犯罪或者处刑较轻的，适用本法。"},{"i":13,"n":"第十三条","txt":"一切危害国家主权、领土完整和安全，分裂国家、颠覆人民民主专政的政权和推翻社会主义制度，破坏社会秩序和经济秩序，侵犯国有财产或者劳动群众集体所有的财产，侵犯公民私人所有的财产，侵犯公民的人身权利、民主权利和其他权利，以及其他危害社会的行为，依照法律应当受刑罚处罚的，都是犯罪，但是情节显著轻微危害不大的，不认为是犯罪。"},{"i":14,"n":"第十四条","txt":"明知自己的行为会发生危害社会的结果，并且希望或者放任这种结果发生，因而构成犯罪的，是故意犯罪。"},{"i":15,"n":"第十五条","txt":"应当预见自己的行为可能发生危害社会的结果，因为疏忽大意而没有预见，或者已经预见而轻信能够避免，以致发生这种结果的，是过失犯罪。"},{"i":16,"n":"第十六条","txt":"行为在客观上虽然造成了损害结果，但是不是出于故意或者过失，而是由于不能抗拒或者不能预见的原因所引起的，不是犯罪。"},{"i":17,"n":"第十七条","txt":"已满十六周岁的人犯罪，应当负刑事责任。"},{"i":18,"n":"第十七条","txt":"已满七十五周岁的人故意犯罪的，可以从轻或者减轻处罚；过失犯罪的，应当从轻或者减轻处罚。"},{"i":19,"n":"第十八条","txt":"精神病人在不能辨认或者不能控制自己行为的时候造成危害结果，经法定程序鉴定确认的，不负刑事责任，但是应当责令他的家属或者监护人严加看管和医疗；在必要的时候，由政府强制医疗。"},{"i":20,"n":"第十九条","txt":"又聋又哑的人或者盲人犯罪，可以从轻、减轻或者免除处罚。"},{"i":21,"n":"第二十条","txt":"为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而采取的制止不法侵害的行为，对不法侵害人造成损害的，属于正当防卫，不负刑事责任。"},{"i":22,"n":"第二十一条","txt":"为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在发生的危险，不得已采取的紧急避险行为，造成损害的，不负刑事责任。"},{"i":23,"n":"第二十二条","txt":"为了犯罪，准备工具、制造条件的，是犯罪预备。"},{"i":24,"n":"第二十三条","txt":"已经着手实行犯罪，由于犯罪分子意志以外的原因而未得逞的，是犯罪未遂。"},{"i":25,"n":"第二十四条","txt":"在犯罪过程中，自动放弃犯罪或者自动有效地防止犯罪结果发生的，是犯罪中止。"},{"i":26,"n":"第二十五条","txt":"共同犯罪是指二人以上共同故意犯罪。"},{"i":27,"n":"第二十六条","txt":"组织、领导犯罪集团进行犯罪活动的或者在共同犯罪中起主要作用的，是主犯。"},{"i":28,"n":"第二十七条","txt":"在共同犯罪中起次要或者辅助作用的，是从犯。"},{"i":29,"n":"第二十八条","txt":"对于被胁迫参加犯罪的，应当按照他的犯罪情节减轻处罚或者免除处罚。"},{"i":30,"n":"第二十九条","txt":"教唆他人犯罪的，应当按照他在共同犯罪中所起的作用处罚。教唆不满十八周岁的人犯罪的，应当从重处罚。"},{"i":31,"n":"第三十条","txt":"公司、企业、事业单位、机关、团体实施的危害社会的行为，法律规定为单位犯罪的，应当负刑事责任。"},{"i":32,"n":"第三十一条","txt":"单位犯罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员判处刑罚。本法分则和其他法律另有规定的，依照规定。"},{"i":33,"n":"第三十二条","txt":"刑罚分为主刑和附加刑。"},{"i":34,"n":"第三十三条","txt":"主刑的种类如下："},{"i":35,"n":"第三十四条","txt":"附加刑的种类如下："},{"i":36,"n":"第三十五条","txt":"对于犯罪的外国人，可以独立适用或者附加适用驱逐出境。"},{"i":37,"n":"第三十六条","txt":"由于犯罪行为而使被害人遭受经济损失的，对犯罪分子除依法给予刑事处罚外，并应根据情况判处赔偿经济损失。"},{"i":38,"n":"第三十七条","txt":"对于犯罪情节轻微不需要判处刑罚的，可以免予刑事处罚，但是可以根据案件的不同情况，予以训诫或者责令具结悔过、赔礼道歉、赔偿损失，或者由主管部门予以行政处罚或者行政处分。"},{"i":39,"n":"第三十七条","txt":"因利用职业便利实施犯罪，或者实施违背职业要求的特定义务的犯罪被判处刑罚的，人民法院可以根据犯罪情况和预防再犯罪的需要，禁止其自刑罚执行完毕之日或者假释之日起从事相关职业，期限为三年至五年。"},{"i":40,"n":"第三十八条","txt":"管制的期限，为三个月以上二年以下。"},{"i":41,"n":"第三十九条","txt":"被判处管制的犯罪分子，在执行期间，应当遵守下列规定："},{"i":42,"n":"第四十条","txt":"被判处管制的犯罪分子，管制期满，执行机关应即向本人和其所在单位或者居住地的群众宣布解除管制。"},{"i":43,"n":"第四十一条","txt":"管制的刑期，从判决执行之日起计算；判决执行以前先行羁押的，羁押一日折抵刑期二日。"},{"i":44,"n":"第四十二条","txt":"拘役的期限，为一个月以上六个月以下。"},{"i":45,"n":"第四十三条","txt":"被判处拘役的犯罪分子，由公安机关就近执行。"},{"i":46,"n":"第四十四条","txt":"拘役的刑期，从判决执行之日起计算；判决执行以前先行羁押的，羁押一日折抵刑期一日。"},{"i":47,"n":"第四十五条","txt":"有期徒刑的期限，除本法第五十条、第六十九条规定外，为六个月以上十五年以下。"},{"i":48,"n":"第四十六条","txt":"被判处有期徒刑、无期徒刑的犯罪分子，在监狱或者其他执行场所执行；凡有劳动能力的，都应当参加劳动，接受教育和改造。"},{"i":49,"n":"第四十七条","txt":"有期徒刑的刑期，从判决执行之日起计算；判决执行以前先行羁押的，羁押一日折抵刑期一日。"},{"i":50,"n":"第四十八条","txt":"死刑只适用于罪行极其严重的犯罪分子。对于应当判处死刑的犯罪分子，如果不是必须立即执行的，可以判处死刑同时宣告缓期二年执行。"},{"i":51,"n":"第四十九条","txt":"犯罪的时候不满十八周岁的人和审判的时候怀孕的妇女，不适用死刑。"},{"i":52,"n":"第五十条","txt":"判处死刑缓期执行的，在死刑缓期执行期间，如果没有故意犯罪，二年期满以后，减为无期徒刑；如果确有重大立功表现，二年期满以后，减为二十五年有期徒刑；如果故意犯罪，情节恶劣的，报请最高人民法院核准后执行死刑；对于故意犯罪未执行死刑的，死刑缓期执行的期间重新计算，并报最高人民法院备案。"},{"i":53,"n":"第五十一条","txt":"死刑缓期执行的期间，从判决确定之日起计算。死刑缓期执行减为有期徒刑的刑期，从死刑缓期执行期满之日起计算。"},{"i":54,"n":"第五十二条","txt":"判处罚金，应当根据犯罪情节决定罚金数额。"},{"i":55,"n":"第五十三条","txt":"罚金在判决指定的期限内一次或者分期缴纳。期满不缴纳的，强制缴纳。对于不能全部缴纳罚金的，人民法院在任何时候发现被执行人有可以执行的财产，应当随时追缴。"},{"i":56,"n":"第五十四条","txt":"剥夺政治权利是剥夺下列权利："},{"i":57,"n":"第五十五条","txt":"剥夺政治权利的期限，除本法第五十七条规定外，为一年以上五年以下。"},{"i":58,"n":"第五十六条","txt":"对于危害国家安全的犯罪分子应当附加剥夺政治权利；对于故意杀人、强奸、放火、爆炸、投毒、抢劫等严重破坏社会秩序的犯罪分子，可以附加剥夺政治权利。"},{"i":59,"n":"第五十七条","txt":"对于被判处死刑、无期徒刑的犯罪分子，应当剥夺政治权利终身。"},{"i":60,"n":"第五十八条","txt":"附加剥夺政治权利的刑期，从徒刑、拘役执行完毕之日或者从假释之日起计算；剥夺政治权利的效力当然施用于主刑执行期间。"},{"i":61,"n":"第五十九条","txt":"没收财产是没收犯罪分子个人所有财产的一部或者全部。没收全部财产的，应当对犯罪分子个人及其扶养的家属保留必需的生活费用。"},{"i":62,"n":"第六十条","txt":"没收财产以前犯罪分子所负的正当债务，需要以没收的财产偿还的，经债权人请求，应当偿还。"},{"i":63,"n":"第六十一条","txt":"对于犯罪分子决定刑罚的时候，应当根据犯罪的事实、犯罪的性质、情节和对于社会的危害程度，依照本法的有关规定判处。"},{"i":64,"n":"第六十二条","txt":"犯罪分子具有本法规定的从重处罚、从轻处罚情节的，应当在法定刑的限度以内判处刑罚。"},{"i":65,"n":"第六十三条","txt":"犯罪分子具有本法规定的减轻处罚情节的，应当在法定刑以下判处刑罚；本法规定有数个量刑幅度的，应当在法定量刑幅度的下一个量刑幅度内判处刑罚。"},{"i":66,"n":"第六十四条","txt":"犯罪分子违法所得的一切财物，应当予以追缴或者责令退赔；对被害人的合法财产，应当及时返还；违禁品和供犯罪所用的本人财物，应当予以没收。没收的财物和罚金，一律上缴国库，不得挪用和自行处理。"},{"i":67,"n":"第六十五条","txt":"被判处有期徒刑以上刑罚的犯罪分子，刑罚执行完毕或者赦免以后，在五年以内再犯应当判处有期徒刑以上刑罚之罪的，是累犯，应当从重处罚，但是过失犯罪和不满十八周岁的人犯罪的除外。"},{"i":68,"n":"第六十六条","txt":"危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪的犯罪分子，在刑罚执行完毕或者赦免以后，在任何时候再犯上述任一类罪的，都以累犯论处。"},{"i":69,"n":"第六十七条","txt":"犯罪以后自动投案，如实供述自己的罪行的，是自首。对于自首的犯罪分子，可以从轻或者减轻处罚。其中，犯罪较轻的，可以免除处罚。"},{"i":70,"n":"第六十八条","txt":"犯罪分子有揭发他人犯罪行为，查证属实的，或者提供重要线索，从而得以侦破其他案件等立功表现的，可以从轻或者减轻处罚；有重大立功表现的，可以减轻或者免除处罚。"},{"i":71,"n":"第六十九条","txt":"判决宣告以前一人犯数罪的，除判处死刑和无期徒刑的以外，应当在总和刑期以下、数刑中最高刑期以上，酌情决定执行的刑期，但是管制最高不能超过三年，拘役最高不能超过一年，有期徒刑总和刑期不满三十五年的，最高不能超过二十年，总和刑期在三十五年以上的，最高不能超过二十五年。"},{"i":72,"n":"第七十条","txt":"判决宣告以后，刑罚执行完毕以前，发现被判刑的犯罪分子在判决宣告以前还有其他罪没有判决的，应当对新发现的罪作出判决，把前后两个判决所判处的刑罚，依照本法第六十九条的规定，决定执行的刑罚。已经执行的刑期，应当计算在新判决决定的刑期以内。"},{"i":73,"n":"第七十一条","txt":"判决宣告以后，刑罚执行完毕以前，被判刑的犯罪分子又犯罪的，应当对新犯的罪作出判决，把前罪没有执行的刑罚和后罪所判处的刑罚，依照本法第六十九条的规定，决定执行的刑罚。"},{"i":74,"n":"第七十二条","txt":"对于被判处拘役、三年以下有期徒刑的犯罪分子，同时符合下列条件的，可以宣告缓刑，对其中不满十八周岁的人、怀孕的妇女和已满七十五周岁的人，应当宣告缓刑："},{"i":75,"n":"第七十三条","txt":"拘役的缓刑考验期限为原判刑期以上一年以下，但是不能少于二个月。"},{"i":76,"n":"第七十四条","txt":"对于累犯和犯罪集团的首要分子，不适用缓刑。"},{"i":77,"n":"第七十五条","txt":"被宣告缓刑的犯罪分子，应当遵守下列规定："},{"i":78,"n":"第七十六条","txt":"对宣告缓刑的犯罪分子，在缓刑考验期限内，依法实行社区矫正，如果没有本法第七十七条规定的情形，缓刑考验期满，原判的刑罚就不再执行，并公开予以宣告。"},{"i":79,"n":"第七十七条","txt":"被宣告缓刑的犯罪分子，在缓刑考验期限内犯新罪或者发现判决宣告以前还有其他罪没有判决的，应当撤销缓刑，对新犯的罪或者新发现的罪作出判决，把前罪和后罪所判处的刑罚，依照本法第六十九条的规定，决定执行的刑罚。"},{"i":80,"n":"第七十八条","txt":"被判处管制、拘役、有期徒刑、无期徒刑的犯罪分子，在执行期间，如果认真遵守监规，接受教育改造，确有悔改表现的，或者有立功表现的，可以减刑；有下列重大立功表现之一的，应当减刑："},{"i":81,"n":"第七十九条","txt":"对于犯罪分子的减刑，由执行机关向中级以上人民法院提出减刑建议书。人民法院应当组成合议庭进行审理，对确有悔改或者立功事实的，裁定予以减刑。非经法定程序不得减刑。"},{"i":82,"n":"第八十条","txt":"无期徒刑减为有期徒刑的刑期，从裁定减刑之日起计算。"},{"i":83,"n":"第八十一条","txt":"被判处有期徒刑的犯罪分子，执行原判刑期二分之一以上，被判处无期徒刑的犯罪分子，实际执行十三年以上，如果认真遵守监规，接受教育改造，确有悔改表现，没有再犯罪的危险的，可以假释。如果有特殊情况，经最高人民法院核准，可以不受上述执行刑期的限制。"},{"i":84,"n":"第八十二条","txt":"对于犯罪分子的假释，依照本法第七十九条规定的程序进行。非经法定程序不得假释。"},{"i":85,"n":"第八十三条","txt":"有期徒刑的假释考验期限，为没有执行完毕的刑期；无期徒刑的假释考验期限为十年。"},{"i":86,"n":"第八十四条","txt":"被宣告假释的犯罪分子，应当遵守下列规定："},{"i":87,"n":"第八十五条","txt":"对假释的犯罪分子，在假释考验期限内，依法实行社区矫正，如果没有本法第八十六条规定的情形，假释考验期满，就认为原判刑罚已经执行完毕，并公开予以宣告。"},{"i":88,"n":"第八十六条","txt":"被假释的犯罪分子，在假释考验期限内犯新罪，应当撤销假释，依照本法第七十一条的规定实行数罪并罚。"},{"i":89,"n":"第八十七条","txt":"犯罪经过下列期限不再追诉："},{"i":90,"n":"第八十八条","txt":"在人民检察院、公安机关、国家安全机关立案侦查或者在人民法院受理案件以后，逃避侦查或者审判的，不受追诉期限的限制。"},{"i":91,"n":"第八十九条","txt":"追诉期限从犯罪之日起计算；犯罪行为有连续或者继续状态的，从犯罪行为终了之日起计算。"},{"i":92,"n":"第九十条","txt":"民族自治地方不能全部适用本法规定的，可以由自治区或者省的人民代表大会根据当地民族的政治、经济、文化的特点和本法规定的基本原则，制定变通或者补充的规定，报请全国人民代表大会常务委员会批准施行。"},{"i":93,"n":"第九十一条","txt":"本法所称公共财产，是指下列财产："},{"i":94,"n":"第九十二条","txt":"本法所称公民私人所有的财产，是指下列财产："},{"i":95,"n":"第九十三条","txt":"本法所称国家工作人员，是指国家机关中从事公务的人员。"},{"i":96,"n":"第九十四条","txt":"本法所称司法工作人员，是指有侦查、检察、审判、监管职责的工作人员。"},{"i":97,"n":"第九十五条","txt":"本法所称重伤，是指有下列情形之一的伤害："},{"i":98,"n":"第九十六条","txt":"本法所称违反国家规定，是指违反全国人民代表大会及其常务委员会制定的法律和决定，国务院制定的行政法规、规定的行政措施、发布的决定和命令。"},{"i":99,"n":"第九十七条","txt":"本法所称首要分子，是指在犯罪集团或者聚众犯罪中起组织、策划、指挥作用的犯罪分子。"},{"i":100,"n":"第九十八条","txt":"本法所称告诉才处理，是指被害人告诉才处理。如果被害人因受强制、威吓无法告诉的，人民检察院和被害人的近亲属也可以告诉。"},{"i":101,"n":"第九十九条","txt":"本法所称以上、以下、以内，包括本数。"},{"i":102,"n":"第一百条","txt":"依法受过刑事处罚的人，在入伍、就业的时候，应当如实向有关单位报告自己曾受过刑事处罚，不得隐瞒。"},{"i":103,"n":"第一百零一条","txt":"本法总则适用于其他有刑罚规定的法律，但是其他法律有特别规定的除外。"},{"i":104,"n":"第一百零二条","txt":"勾结外国，危害中华人民共和国的主权、领土完整和安全的，处无期徒刑或者十年以上有期徒刑。"},{"i":105,"n":"第一百零三条","txt":"组织、策划、实施分裂国家、破坏国家统一的，对首要分子或者罪行重大的，处无期徒刑或者十年以上有期徒刑；对积极参加的，处三年以上十年以下有期徒刑；对其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":106,"n":"第一百零四条","txt":"组织、策划、实施武装叛乱或者武装暴乱的，对首要分子或者罪行重大的，处无期徒刑或者十年以上有期徒刑；对积极参加的，处三年以上十年以下有期徒刑；对其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":107,"n":"第一百零五条","txt":"组织、策划、实施颠覆国家政权、推翻社会主义制度的，对首要分子或者罪行重大的，处无期徒刑或者十年以上有期徒刑；对积极参加的，处三年以上十年以下有期徒刑；对其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":108,"n":"第一百零六条","txt":"与境外机构、组织、个人相勾结，实施本章第一百零三条、第一百零四条、第一百零五条规定之罪的，依照各该条的规定从重处罚。"},{"i":109,"n":"第一百零七条","txt":"境内外机构、组织或者个人资助实施本章第一百零二条、第一百零三条、第一百零四条、第一百零五条规定之罪的，对直接责任人员，处五年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处五年以上有期徒刑。"},{"i":110,"n":"第一百零八条","txt":"投敌叛变的，处三年以上十年以下有期徒刑；情节严重或者带领武装部队人员、人民警察、民兵投敌叛变的，处十年以上有期徒刑或者无期徒刑。"},{"i":111,"n":"第一百零九条","txt":"国家机关工作人员在履行公务期间，擅离岗位，叛逃境外或者在境外叛逃的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处五年以上十年以下有期徒刑。"},{"i":112,"n":"第一百一十条","txt":"有下列间谍行为之一，危害国家安全的，处十年以上有期徒刑或者无期徒刑；情节较轻的，处三年以上十年以下有期徒刑："},{"i":113,"n":"第一百一十一条","txt":"为境外的机构、组织、人员窃取、刺探、收买、非法提供国家秘密或者情报的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑；情节较轻的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":114,"n":"第一百一十二条","txt":"战时供给敌人武器装备、军用物资资敌的，处十年以上有期徒刑或者无期徒刑；情节较轻的，处三年以上十年以下有期徒刑。"},{"i":115,"n":"第一百一十三条","txt":"本章上述危害国家安全罪行中，除第一百零三条第二款、第一百零五条、第一百零七条、第一百零九条外，对国家和人民危害特别严重、情节特别恶劣的，可以判处死刑。"},{"i":116,"n":"第一百一十四条","txt":"放火、决水、爆炸以及投放毒害性、放射性、传染病病原体等物质或者以其他危险方法危害公共安全，尚未造成严重后果的，处三年以上十年以下有期徒刑。"},{"i":117,"n":"第一百一十五条","txt":"放火、决水、爆炸以及投放毒害性、放射性、传染病病原体等物质或者以其他危险方法致人重伤、死亡或者使公私财产遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。"},{"i":118,"n":"第一百一十六条","txt":"破坏火车、汽车、电车、船只、航空器，足以使火车、汽车、电车、船只、航空器发生倾覆、毁坏危险，尚未造成严重后果的，处三年以上十年以下有期徒刑。"},{"i":119,"n":"第一百一十七条","txt":"破坏轨道、桥梁、隧道、公路、机场、航道、灯塔、标志或者进行其他破坏活动，足以使火车、汽车、电车、船只、航空器发生倾覆、毁坏危险，尚未造成严重后果的，处三年以上十年以下有期徒刑。"},{"i":120,"n":"第一百一十八条","txt":"破坏电力、燃气或者其他易燃易爆设备，危害公共安全，尚未造成严重后果的，处三年以上十年以下有期徒刑。"},{"i":121,"n":"第一百一十九条","txt":"破坏交通工具、交通设施、电力设备、燃气设备、易燃易爆设备，造成严重后果的，处十年以上有期徒刑、无期徒刑或者死刑。"},{"i":122,"n":"第一百二十条","txt":"组织、领导恐怖活动组织的，处十年以上有期徒刑或者无期徒刑，并处没收财产；积极参加的，处三年以上十年以下有期徒刑，并处罚金；其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，可以并处罚金。"},{"i":123,"n":"第一百二十条","txt":"资助恐怖活动组织、实施恐怖活动的个人的，或者资助恐怖活动培训的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产。"},{"i":124,"n":"第一百二十条","txt":"有下列情形之一的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产："},{"i":125,"n":"第一百二十条","txt":"以制作、散发宣扬恐怖主义、极端主义的图书、音频视频资料或者其他物品，或者通过讲授、发布信息等方式宣扬恐怖主义、极端主义的，或者煽动实施恐怖活动的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产。"},{"i":126,"n":"第一百二十条","txt":"利用极端主义煽动、胁迫群众破坏国家法律确立的婚姻、司法、教育、社会管理等制度实施的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金；情节特别严重的，处七年以上有期徒刑，并处罚金或者没收财产。"},{"i":127,"n":"第一百二十条","txt":"以暴力、胁迫等方式强制他人在公共场所穿着、佩戴宣扬恐怖主义、极端主义服饰、标志的，处三年以下有期徒刑、拘役或者管制，并处罚金。"},{"i":128,"n":"第一百二十一条","txt":"以暴力、胁迫或者其他方法劫持航空器的，处十年以上有期徒刑或者无期徒刑；致人重伤、死亡或者使航空器遭受严重破坏的，处死刑。"},{"i":129,"n":"第一百二十二条","txt":"以暴力、胁迫或者其他方法劫持船只、汽车的，处五年以上十年以下有期徒刑；造成严重后果的，处十年以上有期徒刑或者无期徒刑。"},{"i":130,"n":"第一百二十三条","txt":"对飞行中的航空器上的人员使用暴力，危及飞行安全，尚未造成严重后果的，处五年以下有期徒刑或者拘役；造成严重后果的，处五年以上有期徒刑。"},{"i":131,"n":"第一百二十四条","txt":"破坏广播电视设施、公用电信设施，危害公共安全的，处三年以上七年以下有期徒刑；造成严重后果的，处七年以上有期徒刑。"},{"i":132,"n":"第一百二十五条","txt":"非法制造、买卖、运输、邮寄、储存枪支、弹药、爆炸物的，处三年以上十年以下有期徒刑；情节严重的，处十年以上有期徒刑、无期徒刑或者死刑。"},{"i":133,"n":"第一百二十六条","txt":"依法被指定、确定的枪支制造企业、销售企业，违反枪支管理规定，有下列行为之一的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑："},{"i":134,"n":"第一百二十七条","txt":"盗窃、抢夺枪支、弹药、爆炸物的，或者盗窃、抢夺毒害性、放射性、传染病病原体等物质，危害公共安全的，处三年以上十年以下有期徒刑；情节严重的，处十年以上有期徒刑、无期徒刑或者死刑。"},{"i":135,"n":"第一百二十八条","txt":"违反枪支管理规定，非法持有、私藏枪支、弹药的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上七年以下有期徒刑。"},{"i":136,"n":"第一百二十九条","txt":"依法配备公务用枪的人员，丢失枪支不及时报告，造成严重后果的，处三年以下有期徒刑或者拘役。"},{"i":137,"n":"第一百三十条","txt":"非法携带枪支、弹药、管制刀具或者爆炸性、易燃性、放射性、毒害性、腐蚀性物品，进入公共场所或者公共交通工具，危及公共安全，情节严重的，处三年以下有期徒刑、拘役或者管制。"},{"i":138,"n":"第一百三十一条","txt":"航空人员违反规章制度，致使发生重大飞行事故，造成严重后果的，处三年以下有期徒刑或者拘役；造成飞机坠毁或者人员死亡的，处三年以上七年以下有期徒刑。"},{"i":139,"n":"第一百三十二条","txt":"铁路职工违反规章制度，致使发生铁路运营安全事故，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。"},{"i":140,"n":"第一百三十三条","txt":"违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；因逃逸致人死亡的，处七年以上有期徒刑。"},{"i":141,"n":"第一百三十三条","txt":"在道路上驾驶机动车，有下列情形之一的，处拘役，并处罚金："},{"i":142,"n":"第一百三十三条","txt":"对行驶中的公共交通工具的驾驶人员使用暴力或者抢控驾驶操纵装置，干扰公共交通工具正常行驶，危及公共安全的，处一年以下有期徒刑、拘役或者管制，并处或者单处罚金。"},{"i":143,"n":"第一百三十四条","txt":"在生产、作业中违反有关安全管理的规定，因而发生重大伤亡事故或者造成其他严重后果的，处三年以下有期徒刑或者拘役；情节特别恶劣的，处三年以上七年以下有期徒刑。"},{"i":144,"n":"第一百三十四条","txt":"在生产、作业中违反有关安全管理的规定，有下列情形之一，具有发生重大伤亡事故或者其他严重后果的现实危险的，处一年以下有期徒刑、拘役或者管制："},{"i":145,"n":"第一百三十五条","txt":"安全生产设施或者安全生产条件不符合国家规定，因而发生重大伤亡事故或者造成其他严重后果的，对直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役；情节特别恶劣的，处三年以上七年以下有期徒刑。"},{"i":146,"n":"第一百三十五条","txt":"举办大型群众性活动违反安全管理规定，因而发生重大伤亡事故或者造成其他严重后果的，对直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役；情节特别恶劣的，处三年以上七年以下有期徒刑。"},{"i":147,"n":"第一百三十六条","txt":"违反爆炸性、易燃性、放射性、毒害性、腐蚀性物品的管理规定，在生产、储存、运输、使用中发生重大事故，造成严重后果的，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。"},{"i":148,"n":"第一百三十七条","txt":"建设单位、设计单位、施工单位、工程监理单位违反国家规定，降低工程质量标准，造成重大安全事故的，对直接责任人员，处五年以下有期徒刑或者拘役，并处罚金；后果特别严重的，处五年以上十年以下有期徒刑，并处罚金。"},{"i":149,"n":"第一百三十八条","txt":"明知校舍或者教育教学设施有危险，而不采取措施或者不及时报告，致使发生重大伤亡事故的，对直接责任人员，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。"},{"i":150,"n":"第一百三十九条","txt":"违反消防管理法规，经消防监督机构通知采取改正措施而拒绝执行，造成严重后果的，对直接责任人员，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。"},{"i":151,"n":"第一百三十九条","txt":"在安全事故发生后，负有报告职责的人员不报或者谎报事故情况，贻误事故抢救，情节严重的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。"},{"i":152,"n":"第一百四十条","txt":"生产者、销售者在产品中掺杂、掺假，以假充真，以次充好或者以不合格产品冒充合格产品，销售金额五万元以上不满二十万元的，处二年以下有期徒刑或者拘役，并处或者单处销售金额百分之五十以上二倍以下罚金；销售金额二十万元以上不满五十万元的，处二年以上七年以下有期徒刑，并处销售金额百分之五十以上二倍以下罚金；销售金额五十万元以上不满二百万元的，处七年以上有期徒刑，并处销售金额百分之五十以上二倍以下罚金；销售金额二百万元以上的，处十五年有期徒刑或者无期徒刑，并处销售金额百分之五十以上二倍以下罚金或者没收财产。"},{"i":153,"n":"第一百四十一条","txt":"生产、销售假药的，处三年以下有期徒刑或者拘役，并处罚金；对人体健康造成严重危害或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；致人死亡或者有其他特别严重情节的，处十年以上有期徒刑、无期徒刑或者死刑，并处罚金或者没收财产。"},{"i":154,"n":"第一百四十二条","txt":"生产、销售劣药，对人体健康造成严重危害的，处三年以上十年以下有期徒刑，并处罚金；后果特别严重的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。"},{"i":155,"n":"第一百四十二条","txt":"违反药品管理法规，有下列情形之一，足以严重危害人体健康的，处三年以下有期徒刑或者拘役，并处或者单处罚金；对人体健康造成严重危害或者有其他严重情节的，处三年以上七年以下有期徒刑，并处罚金："},{"i":156,"n":"第一百四十三条","txt":"生产、销售不符合食品安全标准的食品，足以造成严重食物中毒事故或者其他严重食源性疾病的，处三年以下有期徒刑或者拘役，并处罚金；对人体健康造成严重危害或者有其他严重情节的，处三年以上七年以下有期徒刑，并处罚金；后果特别严重的，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。"},{"i":157,"n":"第一百四十四条","txt":"在生产、销售的食品中掺入有毒、有害的非食品原料的，或者销售明知掺有有毒、有害的非食品原料的食品的，处五年以下有期徒刑，并处罚金；对人体健康造成严重危害或者有其他严重情节的，处五年以上十年以下有期徒刑，并处罚金；致人死亡或者有其他特别严重情节的，依照本法第一百四十一条的规定处罚。"},{"i":158,"n":"第一百四十五条","txt":"生产不符合保障人体健康的国家标准、行业标准的医疗器械、医用卫生材料，或者销售明知是不符合保障人体健康的国家标准、行业标准的医疗器械、医用卫生材料，足以严重危害人体健康的，处三年以下有期徒刑或者拘役，并处销售金额百分之五十以上二倍以下罚金；对人体健康造成严重危害的，处三年以上十年以下有期徒刑，并处销售金额百分之五十以上二倍以下罚金；后果特别严重的，处十年以上有期徒刑或者无期徒刑，并处销售金额百分之五十以上二倍以下罚金或者没收财产。"},{"i":159,"n":"第一百四十六条","txt":"生产不符合保障人身、财产安全的国家标准、行业标准的电器、压力容器、易燃易爆产品或者其他不符合保障人身、财产安全的国家标准、行业标准的产品，或者销售明知是以上不符合保障人身、财产安全的国家标准、行业标准的产品，造成严重后果的，处五年以下有期徒刑，并处销售金额百分之五十以上二倍以下罚金；后果特别严重的，处五年以上有期徒刑，并处销售金额百分之五十以上二倍以下罚金。"},{"i":160,"n":"第一百四十七条","txt":"生产假农药、假兽药、假化肥，销售明知是假的或者失去使用效能的农药、兽药、化肥、种子，或者生产者、销售者以不合格的农药、兽药、化肥、种子冒充合格的农药、兽药、化肥、种子，使生产遭受较大损失的，处三年以下有期徒刑或者拘役，并处或者单处销售金额百分之五十以上二倍以下罚金；使生产遭受重大损失的，处三年以上七年以下有期徒刑，并处销售金额百分之五十以上二倍以下罚金；使生产遭受特别重大损失的，处七年以上有期徒刑或者无期徒刑，并处销售金额百分之五十以上二倍以下罚金或者没收财产。"},{"i":161,"n":"第一百四十八条","txt":"生产不符合卫生标准的化妆品，或者销售明知是不符合卫生标准的化妆品，造成严重后果的，处三年以下有期徒刑或者拘役，并处或者单处销售金额百分之五十以上二倍以下罚金。"},{"i":162,"n":"第一百四十九条","txt":"生产、销售本节第一百四十一条至第一百四十八条所列产品，不构成各该条规定的犯罪，但是销售金额在五万元以上的，依照本节第一百四十条的规定定罪处罚。"},{"i":163,"n":"第一百五十条","txt":"单位犯本节第一百四十条至第一百四十八条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该条的规定处罚。"},{"i":164,"n":"第一百五十一条","txt":"走私武器、弹药、核材料或者伪造的货币的，处七年以上有期徒刑，并处罚金或者没收财产；情节特别严重的，处无期徒刑，并处没收财产；情节较轻的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":165,"n":"第一百五十二条","txt":"以牟利或者传播为目的，走私淫秽的影片、录像带、录音带、图片、书刊或者其他淫秽物品的，处三年以上十年以下有期徒刑，并处罚金；情节严重的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；情节较轻的，处三年以下有期徒刑、拘役或者管制，并处罚金。"},{"i":166,"n":"第一百五十三条","txt":"走私本法第一百五十一条、第一百五十二条、第三百四十七条规定以外的货物、物品的，根据情节轻重，分别依照下列规定处罚："},{"i":167,"n":"第一百五十四条","txt":"下列走私行为，根据本节规定构成犯罪的，依照本法第一百五十三条的规定定罪处罚："},{"i":168,"n":"第一百五十五条","txt":"下列行为，以走私罪论处，依照本节的有关规定处罚："},{"i":169,"n":"第一百五十六条","txt":"与走私罪犯通谋，为其提供贷款、资金、帐号、发票、证明，或者为其提供运输、保管、邮寄或者其他方便的，以走私罪的共犯论处。"},{"i":170,"n":"第一百五十七条","txt":"武装掩护走私的，依照本法第一百五十一条第一款的规定从重处罚。"},{"i":171,"n":"第一百五十八条","txt":"申请公司登记使用虚假证明文件或者采取其他欺诈手段虚报注册资本，欺骗公司登记主管部门，取得公司登记，虚报注册资本数额巨大、后果严重或者有其他严重情节的，处三年以下有期徒刑或者拘役，并处或者单处虚报注册资本金额百分之一以上百分之五以下罚金。"},{"i":172,"n":"第一百五十九条","txt":"公司发起人、股东违反公司法的规定未交付货币、实物或者未转移财产权，虚假出资，或者在公司成立后又抽逃其出资，数额巨大、后果严重或者有其他严重情节的，处五年以下有期徒刑或者拘役，并处或者单处虚假出资金额或者抽逃出资金额百分之二以上百分之十以下罚金。"},{"i":173,"n":"第一百六十条","txt":"在招股说明书、认股书、公司、企业债券募集办法等发行文件中隐瞒重要事实或者编造重大虚假内容，发行股票或者公司、企业债券、存托凭证或者国务院依法认定的其他证券，数额巨大、后果严重或者有其他严重情节的，处五年以下有期徒刑或者拘役，并处或者单处罚金；数额特别巨大、后果特别严重或者有其他特别严重情节的，处五年以上有期徒刑，并处罚金。"},{"i":174,"n":"第一百六十一条","txt":"依法负有信息披露义务的公司、企业向股东和社会公众提供虚假的或者隐瞒重要事实的财务会计报告，或者对依法应当披露的其他重要信息不按照规定披露，严重损害股东或者其他人利益，或者有其他严重情节的，对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处五年以上十年以下有期徒刑，并处罚金。"},{"i":175,"n":"第一百六十二条","txt":"公司、企业进行清算时，隐匿财产，对资产负债表或者财产清单作虚伪记载或者在未清偿债务前分配公司、企业财产，严重损害债权人或者其他人利益的，对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金。"},{"i":176,"n":"第一百六十二条","txt":"隐匿或者故意销毁依法应当保存的会计凭证、会计帐簿、财务会计报告，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金。"},{"i":177,"n":"第一百六十二条","txt":"公司、企业通过隐匿财产、承担虚构的债务或者以其他方法转移、处分财产，实施虚假破产，严重损害债权人或者其他人利益的，对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金。"},{"i":178,"n":"第一百六十三条","txt":"公司、企业或者其他单位的工作人员，利用职务上的便利，索取他人财物或者非法收受他人财物，为他人谋取利益，数额较大的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金。"},{"i":179,"n":"第一百六十四条","txt":"为谋取不正当利益，给予公司、企业或者其他单位的工作人员以财物，数额较大的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大的，处三年以上十年以下有期徒刑，并处罚金。"},{"i":180,"n":"第一百六十五条","txt":"国有公司、企业的董事、经理利用职务便利，自己经营或者为他人经营与其所任职公司、企业同类的营业，获取非法利益，数额巨大的，处三年以下有期徒刑或者拘役，并处或者单处罚金；数额特别巨大的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":181,"n":"第一百六十六条","txt":"国有公司、企业、事业单位的工作人员，利用职务便利，有下列情形之一，使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役，并处或者单处罚金；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑，并处罚金："},{"i":182,"n":"第一百六十七条","txt":"国有公司、企业、事业单位直接负责的主管人员，在签订、履行合同过程中，因严重不负责任被诈骗，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑。"},{"i":183,"n":"第一百六十八条","txt":"国有公司、企业的工作人员，由于严重不负责任或者滥用职权，造成国有公司、企业破产或者严重损失，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑。"},{"i":184,"n":"第一百六十九条","txt":"国有公司、企业或者其上级主管部门直接负责的主管人员，徇私舞弊，将国有资产低价折股或者低价出售，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑。"},{"i":185,"n":"第一百六十九条","txt":"上市公司的董事、监事、高级管理人员违背对公司的忠实义务，利用职务便利，操纵上市公司从事下列行为之一，致使上市公司利益遭受重大损失的，处三年以下有期徒刑或者拘役，并处或者单处罚金；致使上市公司利益遭受特别重大损失的，处三年以上七年以下有期徒刑，并处罚金："},{"i":186,"n":"第一百七十条","txt":"伪造货币的，处三年以上十年以下有期徒刑，并处罚金；有下列情形之一的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产："},{"i":187,"n":"第一百七十一条","txt":"出售、购买伪造的货币或者明知是伪造的货币而运输，数额较大的，处三年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。"},{"i":188,"n":"第一百七十二条","txt":"明知是伪造的货币而持有、使用，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金；数额特别巨大的，处十年以上有期徒刑，并处五万元以上五十万元以下罚金或者没收财产。"},{"i":189,"n":"第一百七十三条","txt":"变造货币，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金。"},{"i":190,"n":"第一百七十四条","txt":"未经国家有关主管部门批准，擅自设立商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构的，处三年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金；情节严重的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金。"},{"i":191,"n":"第一百七十五条","txt":"以转贷牟利为目的，套取金融机构信贷资金高利转贷他人，违法所得数额较大的，处三年以下有期徒刑或者拘役，并处违法所得一倍以上五倍以下罚金；数额巨大的，处三年以上七年以下有期徒刑，并处违法所得一倍以上五倍以下罚金。"},{"i":192,"n":"第一百七十五条","txt":"以欺骗手段取得银行或者其他金融机构贷款、票据承兑、信用证、保函等，给银行或者其他金融机构造成重大损失的，处三年以下有期徒刑或者拘役，并处或者单处罚金；给银行或者其他金融机构造成特别重大损失或者有其他特别严重情节的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":193,"n":"第一百七十六条","txt":"非法吸收公众存款或者变相吸收公众存款，扰乱金融秩序的，处三年以下有期徒刑或者拘役，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑，并处罚金。"},{"i":194,"n":"第一百七十七条","txt":"有下列情形之一，伪造、变造金融票证的，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金；情节严重的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；情节特别严重的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产："},{"i":195,"n":"第一百七十七条","txt":"有下列情形之一，妨害信用卡管理的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；数量巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金："},{"i":196,"n":"第一百七十八条","txt":"伪造、变造国库券或者国家发行的其他有价证券，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。"},{"i":197,"n":"第一百七十九条","txt":"未经国家有关主管部门批准，擅自发行股票或者公司、企业债券，数额巨大、后果严重或者有其他严重情节的，处五年以下有期徒刑或者拘役，并处或者单处非法募集资金金额百分之一以上百分之五以下罚金。"},{"i":198,"n":"第一百八十条","txt":"证券、期货交易内幕信息的知情人员或者非法获取证券、期货交易内幕信息的人员，在涉及证券的发行，证券、期货交易或者其他对证券、期货交易价格有重大影响的信息尚未公开前，买入或者卖出该证券，或者从事与该内幕信息有关的期货交易，或者泄露该信息，或者明示、暗示他人从事上述交易活动，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处违法所得一倍以上五倍以下罚金；情节特别严重的，处五年以上十年以下有期徒刑，并处违法所得一倍以上五倍以下罚金。"},{"i":199,"n":"第一百八十一条","txt":"编造并且传播影响证券、期货交易的虚假信息，扰乱证券、期货交易市场，造成严重后果的，处五年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金。"},{"i":200,"n":"第一百八十二条","txt":"有下列情形之一，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处五年以上十年以下有期徒刑，并处罚金："},{"i":201,"n":"第一百八十三条","txt":"保险公司的工作人员利用职务上的便利，故意编造未曾发生的保险事故进行虚假理赔，骗取保险金归自己所有的，依照本法第二百七十一条的规定定罪处罚。"},{"i":202,"n":"第一百八十四条","txt":"银行或者其他金融机构的工作人员在金融业务活动中索取他人财物或者非法收受他人财物，为他人谋取利益的，或者违反国家规定，收受各种名义的回扣、手续费，归个人所有的，依照本法第一百六十三条的规定定罪处罚。"},{"i":203,"n":"第一百八十五条","txt":"商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构的工作人员利用职务上的便利，挪用本单位或者客户资金的，依照本法第二百七十二条的规定定罪处罚。"},{"i":204,"n":"第一百八十五条","txt":"商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构，违背受托义务，擅自运用客户资金或者其他委托、信托的财产，情节严重的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役，并处三万元以上三十万元以下罚金；情节特别严重的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金。"},{"i":205,"n":"第一百八十六条","txt":"银行或者其他金融机构的工作人员违反国家规定发放贷款，数额巨大或者造成重大损失的，处五年以下有期徒刑或者拘役，并处一万元以上十万元以下罚金；数额特别巨大或者造成特别重大损失的，处五年以上有期徒刑，并处二万元以上二十万元以下罚金。"},{"i":206,"n":"第一百八十七条","txt":"银行或者其他金融机构的工作人员吸收客户资金不入帐，数额巨大或者造成重大损失的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额特别巨大或者造成特别重大损失的，处五年以上有期徒刑，并处五万元以上五十万元以下罚金。"},{"i":207,"n":"第一百八十八条","txt":"银行或者其他金融机构的工作人员违反规定，为他人出具信用证或者其他保函、票据、存单、资信证明，情节严重的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上有期徒刑。"},{"i":208,"n":"第一百八十九条","txt":"银行或者其他金融机构的工作人员在票据业务中，对违反票据法规定的票据予以承兑、付款或者保证，造成重大损失的，处五年以下有期徒刑或者拘役；造成特别重大损失的，处五年以上有期徒刑。"},{"i":209,"n":"第一百九十条","txt":"公司、企业或者其他单位，违反国家规定，擅自将外汇存放境外，或者将境内的外汇非法转移到境外，数额较大的，对单位判处逃汇数额百分之五以上百分之三十以下罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役；数额巨大或者有其他严重情节的，对单位判处逃汇数额百分之五以上百分之三十以下罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以上有期徒刑。"},{"i":210,"n":"第一百九十一条","txt":"为掩饰、隐瞒毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪的所得及其产生的收益的来源和性质，有下列行为之一的，没收实施以上犯罪的所得及其产生的收益，处五年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处五年以上十年以下有期徒刑，并处罚金："},{"i":211,"n":"第一百九十二条","txt":"以非法占有为目的，使用诈骗方法非法集资，数额较大的，处三年以上七年以下有期徒刑，并处罚金；数额巨大或者有其他严重情节的，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。"},{"i":212,"n":"第一百九十三条","txt":"有下列情形之一，以非法占有为目的，诈骗银行或者其他金融机构的贷款，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产："},{"i":213,"n":"第一百九十四条","txt":"有下列情形之一，进行金融票据诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产："},{"i":214,"n":"第一百九十五条","txt":"有下列情形之一，进行信用证诈骗活动的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产："},{"i":215,"n":"第一百九十六条","txt":"有下列情形之一，进行信用卡诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产："},{"i":216,"n":"第一百九十七条","txt":"使用伪造、变造的国库券或者国家发行的其他有价证券，进行诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。"},{"i":217,"n":"第一百九十八条","txt":"有下列情形之一，进行保险诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处一万元以上十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑，并处二万元以上二十万元以下罚金或者没收财产："},{"i":218,"n":"第一百九十九条","txt":"（删去）"},{"i":219,"n":"第二百条","txt":"单位犯本节第一百九十四条、第一百九十五条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，可以并处罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金。"},{"i":220,"n":"第二百零一条","txt":"纳税人采取欺骗、隐瞒手段进行虚假纳税申报或者不申报，逃避缴纳税款数额较大并且占应纳税额百分之十以上的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大并且占应纳税额百分之三十以上的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":221,"n":"第二百零二条","txt":"以暴力、威胁方法拒不缴纳税款的，处三年以下有期徒刑或者拘役，并处拒缴税款一倍以上五倍以下罚金；情节严重的，处三年以上七年以下有期徒刑，并处拒缴税款一倍以上五倍以下罚金。"},{"i":222,"n":"第二百零三条","txt":"纳税人欠缴应纳税款，采取转移或者隐匿财产的手段，致使税务机关无法追缴欠缴的税款，数额在一万元以上不满十万元的，处三年以下有期徒刑或者拘役，并处或者单处欠缴税款一倍以上五倍以下罚金；数额在十万元以上的，处三年以上七年以下有期徒刑，并处欠缴税款一倍以上五倍以下罚金。"},{"i":223,"n":"第二百零四条","txt":"以假报出口或者其他欺骗手段，骗取国家出口退税款，数额较大的，处五年以下有期徒刑或者拘役，并处骗取税款一倍以上五倍以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处骗取税款一倍以上五倍以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处骗取税款一倍以上五倍以下罚金或者没收财产。"},{"i":224,"n":"第二百零五条","txt":"虚开增值税专用发票或者虚开用于骗取出口退税、抵扣税款的其他发票的，处三年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；虚开的税款数额较大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；虚开的税款数额巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。"},{"i":225,"n":"第二百零五条","txt":"虚开本法第二百零五条规定以外的其他发票，情节严重的，处二年以下有期徒刑、拘役或者管制，并处罚金；情节特别严重的，处二年以上七年以下有期徒刑，并处罚金。"},{"i":226,"n":"第二百零六条","txt":"伪造或者出售伪造的增值税专用发票的，处三年以下有期徒刑、拘役或者管制，并处二万元以上二十万元以下罚金；数量较大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数量巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。"},{"i":227,"n":"第二百零七条","txt":"非法出售增值税专用发票的，处三年以下有期徒刑、拘役或者管制，并处二万元以上二十万元以下罚金；数量较大的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数量巨大的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。"},{"i":228,"n":"第二百零八条","txt":"非法购买增值税专用发票或者购买伪造的增值税专用发票的，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金。"},{"i":229,"n":"第二百零九条","txt":"伪造、擅自制造或者出售伪造、擅自制造的可以用于骗取出口退税、抵扣税款的其他发票的，处三年以下有期徒刑、拘役或者管制，并处二万元以上二十万元以下罚金；数量巨大的，处三年以上七年以下有期徒刑，并处五万元以上五十万元以下罚金；数量特别巨大的，处七年以上有期徒刑，并处五万元以上五十万元以下罚金或者没收财产。"},{"i":230,"n":"第二百一十条","txt":"盗窃增值税专用发票或者可以用于骗取出口退税、抵扣税款的其他发票的，依照本法第二百六十四条的规定定罪处罚。"},{"i":231,"n":"第二百一十条","txt":"明知是伪造的发票而持有，数量较大的，处二年以下有期徒刑、拘役或者管制，并处罚金；数量巨大的，处二年以上七年以下有期徒刑，并处罚金。"},{"i":232,"n":"第二百一十一条","txt":"单位犯本节第二百零一条、第二百零三条、第二百零四条、第二百零七条、第二百零八条、第二百零九条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该条的规定处罚。"},{"i":233,"n":"第二百一十二条","txt":"犯本节第二百零一条至第二百零五条规定之罪，被判处罚金、没收财产的，在执行前，应当先由税务机关追缴税款和所骗取的出口退税款。"},{"i":234,"n":"第二百一十三条","txt":"未经注册商标所有人许可，在同一种商品、服务上使用与其注册商标相同的商标，情节严重的，处三年以下有期徒刑，并处或者单处罚金；情节特别严重的，处三年以上十年以下有期徒刑，并处罚金。"},{"i":235,"n":"第二百一十四条","txt":"销售明知是假冒注册商标的商品，违法所得数额较大或者有其他严重情节的，处三年以下有期徒刑，并处或者单处罚金；违法所得数额巨大或者有其他特别严重情节的，处三年以上十年以下有期徒刑，并处罚金。"},{"i":236,"n":"第二百一十五条","txt":"伪造、擅自制造他人注册商标标识或者销售伪造、擅自制造的注册商标标识，情节严重的，处三年以下有期徒刑，并处或者单处罚金；情节特别严重的，处三年以上十年以下有期徒刑，并处罚金。"},{"i":237,"n":"第二百一十六条","txt":"假冒他人专利，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":238,"n":"第二百一十七条","txt":"以营利为目的，有下列侵犯著作权或者与著作权有关的权利的情形之一，违法所得数额较大或者有其他严重情节的，处三年以下有期徒刑，并处或者单处罚金；违法所得数额巨大或者有其他特别严重情节的，处三年以上十年以下有期徒刑，并处罚金："},{"i":239,"n":"第二百一十八条","txt":"以营利为目的，销售明知是本法第二百一十七条规定的侵权复制品，违法所得数额巨大或者有其他严重情节的，处五年以下有期徒刑，并处或者单处罚金。"},{"i":240,"n":"第二百一十九条","txt":"有下列侵犯商业秘密行为之一，情节严重的，处三年以下有期徒刑，并处或者单处罚金；情节特别严重的，处三年以上十年以下有期徒刑，并处罚金："},{"i":241,"n":"第二百一十九条","txt":"为境外的机构、组织、人员窃取、刺探、收买、非法提供商业秘密的，处五年以下有期徒刑，并处或者单处罚金；情节严重的，处五年以上有期徒刑，并处罚金。"},{"i":242,"n":"第二百二十条","txt":"单位犯本节第二百一十三条至第二百一十九条之一规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本节各该条的规定处罚。"},{"i":243,"n":"第二百二十一条","txt":"捏造并散布虚伪事实，损害他人的商业信誉、商品声誉，给他人造成重大损失或者有其他严重情节的，处二年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":244,"n":"第二百二十二条","txt":"广告主、广告经营者、广告发布者违反国家规定，利用广告对商品或者服务作虚假宣传，情节严重的，处二年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":245,"n":"第二百二十三条","txt":"投标人相互串通投标报价，损害招标人或者其他投标人利益，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":246,"n":"第二百二十四条","txt":"有下列情形之一，以非法占有为目的，在签订、履行合同过程中，骗取对方当事人财物，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产："},{"i":247,"n":"第二百二十四条","txt":"组织、领导以推销商品、提供服务等经营活动为名，要求参加者以缴纳费用或者购买商品、服务等方式获得加入资格，并按照一定顺序组成层级，直接或者间接以发展人员的数量作为计酬或者返利依据，引诱、胁迫参加者继续发展他人参加，骗取财物，扰乱经济社会秩序的传销活动的，处五年以下有期徒刑或者拘役，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金。"},{"i":248,"n":"第二百二十五条","txt":"违反国家规定，有下列非法经营行为之一，扰乱市场秩序，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处违法所得一倍以上五倍以下罚金；情节特别严重的，处五年以上有期徒刑，并处违法所得一倍以上五倍以下罚金或者没收财产："},{"i":249,"n":"第二百二十六条","txt":"以暴力、威胁手段，实施下列行为之一，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金："},{"i":250,"n":"第二百二十七条","txt":"伪造或者倒卖伪造的车票、船票、邮票或者其他有价票证，数额较大的，处二年以下有期徒刑、拘役或者管制，并处或者单处票证价额一倍以上五倍以下罚金；数额巨大的，处二年以上七年以下有期徒刑，并处票证价额一倍以上五倍以下罚金。"},{"i":251,"n":"第二百二十八条","txt":"以牟利为目的，违反土地管理法规，非法转让、倒卖土地使用权，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处非法转让、倒卖土地使用权价额百分之五以上百分之二十以下罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处非法转让、倒卖土地使用权价额百分之五以上百分之二十以下罚金。"},{"i":252,"n":"第二百二十九条","txt":"承担资产评估、验资、验证、会计、审计、法律服务、保荐、安全评价、环境影响评价、环境监测等职责的中介组织的人员故意提供虚假证明文件，情节严重的，处五年以下有期徒刑或者拘役，并处罚金；有下列情形之一的，处五年以上十年以下有期徒刑，并处罚金："},{"i":253,"n":"第二百三十条","txt":"违反进出口商品检验法的规定，逃避商品检验，将必须经商检机构检验的进口商品未报经检验而擅自销售、使用，或者将必须经商检机构检验的出口商品未报经检验合格而擅自出口，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":254,"n":"第二百三十一条","txt":"单位犯本节第二百二十一条至第二百三十条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本节各该条的规定处罚。"},{"i":255,"n":"第二百三十二条","txt":"故意杀人的，处死刑、无期徒刑或者十年以上有期徒刑；情节较轻的，处三年以上十年以下有期徒刑。"},{"i":256,"n":"第二百三十三条","txt":"过失致人死亡的，处三年以上七年以下有期徒刑；情节较轻的，处三年以下有期徒刑。本法另有规定的，依照规定。"},{"i":257,"n":"第二百三十四条","txt":"故意伤害他人身体的，处三年以下有期徒刑、拘役或者管制。"},{"i":258,"n":"第二百三十四条","txt":"组织他人出卖人体器官的，处五年以下有期徒刑，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产。"},{"i":259,"n":"第二百三十五条","txt":"过失伤害他人致人重伤的，处三年以下有期徒刑或者拘役。本法另有规定的，依照规定。"},{"i":260,"n":"第二百三十六条","txt":"以暴力、胁迫或者其他手段强奸妇女的，处三年以上十年以下有期徒刑。"},{"i":261,"n":"第二百三十六条","txt":"对已满十四周岁不满十六周岁的未成年女性负有监护、收养、看护、教育、医疗等特殊职责的人员，与该未成年女性发生性关系的，处三年以下有期徒刑；情节恶劣的，处三年以上十年以下有期徒刑。"},{"i":262,"n":"第二百三十七条","txt":"以暴力、胁迫或者其他方法强制猥亵他人或者侮辱妇女的，处五年以下有期徒刑或者拘役。"},{"i":263,"n":"第二百三十八条","txt":"非法拘禁他人或者以其他方法非法剥夺他人人身自由的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。具有殴打、侮辱情节的，从重处罚。"},{"i":264,"n":"第二百三十九条","txt":"以勒索财物为目的绑架他人的，或者绑架他人作为人质的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；情节较轻的，处五年以上十年以下有期徒刑，并处罚金。"},{"i":265,"n":"第二百四十条","txt":"拐卖妇女、儿童的，处五年以上十年以下有期徒刑，并处罚金；有下列情形之一的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；情节特别严重的，处死刑，并处没收财产："},{"i":266,"n":"第二百四十一条","txt":"收买被拐卖的妇女、儿童的，处三年以下有期徒刑、拘役或者管制。"},{"i":267,"n":"第二百四十二条","txt":"以暴力、威胁方法阻碍国家机关工作人员解救被收买的妇女、儿童的，依照本法第二百七十七条的规定定罪处罚。"},{"i":268,"n":"第二百四十三条","txt":"捏造事实诬告陷害他人，意图使他人受刑事追究，情节严重的，处三年以下有期徒刑、拘役或者管制；造成严重后果的，处三年以上十年以下有期徒刑。"},{"i":269,"n":"第二百四十四条","txt":"以暴力、威胁或者限制人身自由的方法强迫他人劳动的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。"},{"i":270,"n":"第二百四十四条","txt":"违反劳动管理法规，雇用未满十六周岁的未成年人从事超强度体力劳动的，或者从事高空、井下作业的，或者在爆炸性、易燃性、放射性、毒害性等危险环境下从事劳动，情节严重的，对直接责任人员，处三年以下有期徒刑或者拘役，并处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":271,"n":"第二百四十五条","txt":"非法搜查他人身体、住宅，或者非法侵入他人住宅的，处三年以下有期徒刑或者拘役。"},{"i":272,"n":"第二百四十六条","txt":"以暴力或者其他方法公然侮辱他人或者捏造事实诽谤他人，情节严重的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":273,"n":"第二百四十七条","txt":"司法工作人员对犯罪嫌疑人、被告人实行刑讯逼供或者使用暴力逼取证人证言的，处三年以下有期徒刑或者拘役。致人伤残、死亡的，依照本法第二百三十四条、第二百三十二条的规定定罪从重处罚。"},{"i":274,"n":"第二百四十八条","txt":"监狱、拘留所、看守所等监管机构的监管人员对被监管人进行殴打或者体罚虐待，情节严重的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上十年以下有期徒刑。致人伤残、死亡的，依照本法第二百三十四条、第二百三十二条的规定定罪从重处罚。"},{"i":275,"n":"第二百四十九条","txt":"煽动民族仇恨、民族歧视，情节严重的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节特别严重的，处三年以上十年以下有期徒刑。"},{"i":276,"n":"第二百五十条","txt":"在出版物中刊载歧视、侮辱少数民族的内容，情节恶劣，造成严重后果的，对直接责任人员，处三年以下有期徒刑、拘役或者管制。"},{"i":277,"n":"第二百五十一条","txt":"国家机关工作人员非法剥夺公民的宗教信仰自由和侵犯少数民族风俗习惯，情节严重的，处二年以下有期徒刑或者拘役。"},{"i":278,"n":"第二百五十二条","txt":"隐匿、毁弃或者非法开拆他人信件，侵犯公民通信自由权利，情节严重的，处一年以下有期徒刑或者拘役。"},{"i":279,"n":"第二百五十三条","txt":"邮政工作人员私自开拆或者隐匿、毁弃邮件、电报的，处二年以下有期徒刑或者拘役。"},{"i":280,"n":"第二百五十三条","txt":"违反国家有关规定，向他人出售或者提供公民个人信息，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":281,"n":"第二百五十四条","txt":"国家机关工作人员滥用职权、假公济私，对控告人、申诉人、批评人、举报人实行报复陷害的，处二年以下有期徒刑或者拘役；情节严重的，处二年以上七年以下有期徒刑。"},{"i":282,"n":"第二百五十五条","txt":"公司、企业、事业单位、机关、团体的领导人，对依法履行职责、抵制违反会计法、统计法行为的会计、统计人员实行打击报复，情节恶劣的，处三年以下有期徒刑或者拘役。"},{"i":283,"n":"第二百五十六条","txt":"在选举各级人民代表大会代表和国家机关领导人员时，以暴力、威胁、欺骗、贿赂、伪造选举文件、虚报选举票数等手段破坏选举或者妨害选民和代表自由行使选举权和被选举权，情节严重的，处三年以下有期徒刑、拘役或者剥夺政治权利。"},{"i":284,"n":"第二百五十七条","txt":"以暴力干涉他人婚姻自由的，处二年以下有期徒刑或者拘役。"},{"i":285,"n":"第二百五十八条","txt":"有配偶而重婚的，或者明知他人有配偶而与之结婚的，处二年以下有期徒刑或者拘役。"},{"i":286,"n":"第二百五十九条","txt":"明知是现役军人的配偶而与之同居或者结婚的，处三年以下有期徒刑或者拘役。"},{"i":287,"n":"第二百六十条","txt":"虐待家庭成员，情节恶劣的，处二年以下有期徒刑、拘役或者管制。"},{"i":288,"n":"第二百六十条","txt":"对未成年人、老年人、患病的人、残疾人等负有监护、看护职责的人虐待被监护、看护的人，情节恶劣的，处三年以下有期徒刑或者拘役。"},{"i":289,"n":"第二百六十一条","txt":"对于年老、年幼、患病或者其他没有独立生活能力的人，负有扶养义务而拒绝扶养，情节恶劣的，处五年以下有期徒刑、拘役或者管制。"},{"i":290,"n":"第二百六十二条","txt":"拐骗不满十四周岁的未成年人，脱离家庭或者监护人的，处五年以下有期徒刑或者拘役。"},{"i":291,"n":"第二百六十二条","txt":"以暴力、胁迫手段组织残疾人或者不满十四周岁的未成年人乞讨的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":292,"n":"第二百六十二条","txt":"组织未成年人进行盗窃、诈骗、抢夺、敲诈勒索等违反治安管理活动的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":293,"n":"第二百六十三条","txt":"以暴力、胁迫或者其他方法抢劫公私财物的，处三年以上十年以下有期徒刑，并处罚金；有下列情形之一的，处十年以上有期徒刑、无期徒刑或者死刑，并处罚金或者没收财产："},{"i":294,"n":"第二百六十四条","txt":"盗窃公私财物，数额较大的，或者多次盗窃、入户盗窃、携带凶器盗窃、扒窃的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。"},{"i":295,"n":"第二百六十五条","txt":"以牟利为目的，盗接他人通信线路、复制他人电信码号或者明知是盗接、复制的电信设备、设施而使用的，依照本法第二百六十四条的规定定罪处罚。"},{"i":296,"n":"第二百六十六条","txt":"诈骗公私财物，数额较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。本法另有规定的，依照规定。"},{"i":297,"n":"第二百六十七条","txt":"抢夺公私财物，数额较大的，或者多次抢夺的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。"},{"i":298,"n":"第二百六十八条","txt":"聚众哄抢公私财物，数额较大或者有其他严重情节的，对首要分子和积极参加的，处三年以下有期徒刑、拘役或者管制，并处罚金；数额巨大或者有其他特别严重情节的，处三年以上十年以下有期徒刑，并处罚金。"},{"i":299,"n":"第二百六十九条","txt":"犯盗窃、诈骗、抢夺罪，为窝藏赃物、抗拒抓捕或者毁灭罪证而当场使用暴力或者以暴力相威胁的，依照本法第二百六十三条的规定定罪处罚。"},{"i":300,"n":"第二百七十条","txt":"将代为保管的他人财物非法占为己有，数额较大，拒不退还的，处二年以下有期徒刑、拘役或者罚金；数额巨大或者有其他严重情节的，处二年以上五年以下有期徒刑，并处罚金。"},{"i":301,"n":"第二百七十一条","txt":"公司、企业或者其他单位的工作人员，利用职务上的便利，将本单位财物非法占为己有，数额较大的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大的，处十年以上有期徒刑或者无期徒刑，并处罚金。"},{"i":302,"n":"第二百七十二条","txt":"公司、企业或者其他单位的工作人员，利用职务上的便利，挪用本单位资金归个人使用或者借贷给他人，数额较大、超过三个月未还的，或者虽未超过三个月，但数额较大、进行营利活动的，或者进行非法活动的，处三年以下有期徒刑或者拘役；挪用本单位资金数额巨大的，处三年以上七年以下有期徒刑；数额特别巨大的，处七年以上有期徒刑。"},{"i":303,"n":"第二百七十三条","txt":"挪用用于救灾、抢险、防汛、优抚、扶贫、移民、救济款物，情节严重，致使国家和人民群众利益遭受重大损害的，对直接责任人员，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。"},{"i":304,"n":"第二百七十四条","txt":"敲诈勒索公私财物，数额较大或者多次敲诈勒索的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑，并处罚金。"},{"i":305,"n":"第二百七十五条","txt":"故意毁坏公私财物，数额较大或者有其他严重情节的，处三年以下有期徒刑、拘役或者罚金；数额巨大或者有其他特别严重情节的，处三年以上七年以下有期徒刑。"},{"i":306,"n":"第二百七十六条","txt":"由于泄愤报复或者其他个人目的，毁坏机器设备、残害耕畜或者以其他方法破坏生产经营的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上七年以下有期徒刑。"},{"i":307,"n":"第二百七十六条","txt":"以转移财产、逃匿等方法逃避支付劳动者的劳动报酬或者有能力支付而不支付劳动者的劳动报酬，数额较大，经政府有关部门责令支付仍不支付的，处三年以下有期徒刑或者拘役，并处或者单处罚金；造成严重后果的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":308,"n":"第二百七十七条","txt":"以暴力、威胁方法阻碍国家机关工作人员依法执行职务的，处三年以下有期徒刑、拘役、管制或者罚金。"},{"i":309,"n":"第二百七十八条","txt":"煽动群众暴力抗拒国家法律、行政法规实施的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；造成严重后果的，处三年以上七年以下有期徒刑。"},{"i":310,"n":"第二百七十九条","txt":"冒充国家机关工作人员招摇撞骗的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上十年以下有期徒刑。"},{"i":311,"n":"第二百八十条","txt":"伪造、变造、买卖或者盗窃、抢夺、毁灭国家机关的公文、证件、印章的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。"},{"i":312,"n":"第二百八十条","txt":"在依照国家规定应当提供身份证明的活动中，使用伪造、变造的或者盗用他人的居民身份证、护照、社会保障卡、驾驶证等依法可以用于证明身份的证件，情节严重的，处拘役或者管制，并处或者单处罚金。"},{"i":313,"n":"第二百八十条","txt":"盗用、冒用他人身份，顶替他人取得的高等学历教育入学资格、公务员录用资格、就业安置待遇的，处三年以下有期徒刑、拘役或者管制，并处罚金。"},{"i":314,"n":"第二百八十一条","txt":"非法生产、买卖人民警察制式服装、车辆号牌等专用标志、警械，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。"},{"i":315,"n":"第二百八十二条","txt":"以窃取、刺探、收买方法，非法获取国家秘密的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上七年以下有期徒刑。"},{"i":316,"n":"第二百八十三条","txt":"非法生产、销售专用间谍器材或者窃听、窃照专用器材的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":317,"n":"第二百八十四条","txt":"非法使用窃听、窃照专用器材，造成严重后果的，处二年以下有期徒刑、拘役或者管制。"},{"i":318,"n":"第二百八十四条","txt":"在法律规定的国家考试中，组织作弊的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":319,"n":"第二百八十五条","txt":"违反国家规定，侵入国家事务、国防建设、尖端科学技术领域的计算机信息系统的，处三年以下有期徒刑或者拘役。"},{"i":320,"n":"第二百八十六条","txt":"违反国家规定，对计算机信息系统功能进行删除、修改、增加、干扰，造成计算机信息系统不能正常运行，后果严重的，处五年以下有期徒刑或者拘役；后果特别严重的，处五年以上有期徒刑。"},{"i":321,"n":"第二百八十六条","txt":"网络服务提供者不履行法律、行政法规规定的信息网络安全管理义务，经监管部门责令采取改正措施而拒不改正，有下列情形之一的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金："},{"i":322,"n":"第二百八十七条","txt":"利用计算机实施金融诈骗、盗窃、贪污、挪用公款、窃取国家秘密或者其他犯罪的，依照本法有关规定定罪处罚。"},{"i":323,"n":"第二百八十七条","txt":"利用信息网络实施下列行为之一，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金："},{"i":324,"n":"第二百八十七条","txt":"明知他人利用信息网络实施犯罪，为其犯罪提供互联网接入、服务器托管、网络存储、通讯传输等技术支持，或者提供广告推广、支付结算等帮助，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":325,"n":"第二百八十八条","txt":"违反国家规定，擅自设置、使用无线电台（站），或者擅自使用无线电频率，干扰无线电通讯秩序，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":326,"n":"第二百八十九条","txt":"聚众“打砸抢”，致人伤残、死亡的，依照本法第二百三十四条、第二百三十二条的规定定罪处罚。毁坏或者抢走公私财物的，除判令退赔外，对首要分子，依照本法第二百六十三条的规定定罪处罚。"},{"i":327,"n":"第二百九十条","txt":"聚众扰乱社会秩序，情节严重，致使工作、生产、营业和教学、科研、医疗无法进行，造成严重损失的，对首要分子，处三年以上七年以下有期徒刑；对其他积极参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":328,"n":"第二百九十一条","txt":"聚众扰乱车站、码头、民用航空站、商场、公园、影剧院、展览会、运动场或者其他公共场所秩序，聚众堵塞交通或者破坏交通秩序，抗拒、阻碍国家治安管理工作人员依法执行职务，情节严重的，对首要分子，处五年以下有期徒刑、拘役或者管制。"},{"i":329,"n":"第二百九十一条","txt":"投放虚假的爆炸性、毒害性、放射性、传染病病原体等物质，或者编造爆炸威胁、生化威胁、放射威胁等恐怖信息，或者明知是编造的恐怖信息而故意传播，严重扰乱社会秩序的，处五年以下有期徒刑、拘役或者管制；造成严重后果的，处五年以上有期徒刑。"},{"i":330,"n":"第二百九十一条","txt":"从建筑物或者其他高空抛掷物品，情节严重的，处一年以下有期徒刑、拘役或者管制，并处或者单处罚金。"},{"i":331,"n":"第二百九十二条","txt":"聚众斗殴的，对首要分子和其他积极参加的，处三年以下有期徒刑、拘役或者管制；有下列情形之一的，对首要分子和其他积极参加的，处三年以上十年以下有期徒刑："},{"i":332,"n":"第二百九十三条","txt":"有下列寻衅滋事行为之一，破坏社会秩序的，处五年以下有期徒刑、拘役或者管制："},{"i":333,"n":"第二百九十三条","txt":"有下列情形之一，催收高利放贷等产生的非法债务，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金："},{"i":334,"n":"第二百九十四条","txt":"组织、领导黑社会性质的组织的，处七年以上有期徒刑，并处没收财产；积极参加的，处三年以上七年以下有期徒刑，可以并处罚金或者没收财产；其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，可以并处罚金。"},{"i":335,"n":"第二百九十五条","txt":"传授犯罪方法的，处五年以下有期徒刑、拘役或者管制；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑。"},{"i":336,"n":"第二百九十六条","txt":"举行集会、游行、示威，未依照法律规定申请或者申请未获许可，或者未按照主管机关许可的起止时间、地点、路线进行，又拒不服从解散命令，严重破坏社会秩序的，对集会、游行、示威的负责人和直接责任人员，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":337,"n":"第二百九十七条","txt":"违反法律规定，携带武器、管制刀具或者爆炸物参加集会、游行、示威的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":338,"n":"第二百九十八条","txt":"扰乱、冲击或者以其他方法破坏依法举行的集会、游行、示威，造成公共秩序混乱的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":339,"n":"第二百九十九条","txt":"在公共场合，故意以焚烧、毁损、涂划、玷污、践踏等方式侮辱中华人民共和国国旗、国徽的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":340,"n":"第二百九十九条","txt":"侮辱、诽谤或者以其他方式侵害英雄烈士的名誉、荣誉，损害社会公共利益，情节严重的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":341,"n":"第三百条","txt":"组织、利用会道门、邪教组织或者利用迷信破坏国家法律、行政法规实施的，处三年以上七年以下有期徒刑，并处罚金；情节特别严重的，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；情节较轻的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，并处或者单处罚金。"},{"i":342,"n":"第三百零一条","txt":"聚众进行淫乱活动的，对首要分子或者多次参加的，处五年以下有期徒刑、拘役或者管制。"},{"i":343,"n":"第三百零二条","txt":"盗窃、侮辱、故意毁坏尸体、尸骨、骨灰的，处三年以下有期徒刑、拘役或者管制。"},{"i":344,"n":"第三百零三条","txt":"以营利为目的，聚众赌博或者以赌博为业的，处三年以下有期徒刑、拘役或者管制，并处罚金。"},{"i":345,"n":"第三百零四条","txt":"邮政工作人员严重不负责任，故意延误投递邮件，致使公共财产、国家和人民利益遭受重大损失的，处二年以下有期徒刑或者拘役。"},{"i":346,"n":"第三百零五条","txt":"在刑事诉讼中，证人、鉴定人、记录人、翻译人对与案件有重要关系的情节，故意作虚假证明、鉴定、记录、翻译，意图陷害他人或者隐匿罪证的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。"},{"i":347,"n":"第三百零六条","txt":"在刑事诉讼中，辩护人、诉讼代理人毁灭、伪造证据，帮助当事人毁灭、伪造证据，威胁、引诱证人违背事实改变证言或者作伪证的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。"},{"i":348,"n":"第三百零七条","txt":"以暴力、威胁、贿买等方法阻止证人作证或者指使他人作伪证的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。"},{"i":349,"n":"第三百零七条","txt":"以捏造的事实提起民事诉讼，妨害司法秩序或者严重侵害他人合法权益的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":350,"n":"第三百零八条","txt":"对证人进行打击报复的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。"},{"i":351,"n":"第三百零八条","txt":"司法工作人员、辩护人、诉讼代理人或者其他诉讼参与人，泄露依法不公开审理的案件中不应当公开的信息，造成信息公开传播或者其他严重后果的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。"},{"i":352,"n":"第三百零九条","txt":"有下列扰乱法庭秩序情形之一的，处三年以下有期徒刑、拘役、管制或者罚金："},{"i":353,"n":"第三百一十条","txt":"明知是犯罪的人而为其提供隐藏处所、财物，帮助其逃匿或者作假证明包庇的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上十年以下有期徒刑。"},{"i":354,"n":"第三百一十一条","txt":"明知他人有间谍犯罪或者恐怖主义、极端主义犯罪行为，在司法机关向其调查有关情况、收集有关证据时，拒绝提供，情节严重的，处三年以下有期徒刑、拘役或者管制。"},{"i":355,"n":"第三百一十二条","txt":"明知是犯罪所得及其产生的收益而予以窝藏、转移、收购、代为销售或者以其他方法掩饰、隐瞒的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":356,"n":"第三百一十三条","txt":"对人民法院的判决、裁定有能力执行而拒不执行，情节严重的，处三年以下有期徒刑、拘役或者罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":357,"n":"第三百一十四条","txt":"隐藏、转移、变卖、故意毁损已被司法机关查封、扣押、冻结的财产，情节严重的，处三年以下有期徒刑、拘役或者罚金。"},{"i":358,"n":"第三百一十五条","txt":"依法被关押的罪犯，有下列破坏监管秩序行为之一，情节严重的，处三年以下有期徒刑："},{"i":359,"n":"第三百一十六条","txt":"依法被关押的罪犯、被告人、犯罪嫌疑人脱逃的，处五年以下有期徒刑或者拘役。"},{"i":360,"n":"第三百一十七条","txt":"组织越狱的首要分子和积极参加的，处五年以上有期徒刑；其他参加的，处五年以下有期徒刑或者拘役。"},{"i":361,"n":"第三百一十八条","txt":"组织他人偷越国（边）境的，处二年以上七年以下有期徒刑，并处罚金；有下列情形之一的，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产："},{"i":362,"n":"第三百一十九条","txt":"以劳务输出、经贸往来或者其他名义，弄虚作假，骗取护照、签证等出境证件，为组织他人偷越国（边）境使用的，处三年以下有期徒刑，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。"},{"i":363,"n":"第三百二十条","txt":"为他人提供伪造、变造的护照、签证等出入境证件，或者出售护照、签证等出入境证件的，处五年以下有期徒刑，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金。"},{"i":364,"n":"第三百二十一条","txt":"运送他人偷越国（边）境的，处五年以下有期徒刑、拘役或者管制，并处罚金；有下列情形之一的，处五年以上十年以下有期徒刑，并处罚金："},{"i":365,"n":"第三百二十二条","txt":"违反国（边）境管理法规，偷越国（边）境，情节严重的，处一年以下有期徒刑、拘役或者管制，并处罚金；为参加恐怖活动组织、接受恐怖活动培训或者实施恐怖活动，偷越国（边）境的，处一年以上三年以下有期徒刑，并处罚金。"},{"i":366,"n":"第三百二十三条","txt":"故意破坏国家边境的界碑、界桩或者永久性测量标志的，处三年以下有期徒刑或者拘役。"},{"i":367,"n":"第三百二十四条","txt":"故意损毁国家保护的珍贵文物或者被确定为全国重点文物保护单位、省级文物保护单位的文物的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。"},{"i":368,"n":"第三百二十五条","txt":"违反文物保护法规，将收藏的国家禁止出口的珍贵文物私自出售或者私自赠送给外国人的，处五年以下有期徒刑或者拘役，可以并处罚金。"},{"i":369,"n":"第三百二十六条","txt":"以牟利为目的，倒卖国家禁止经营的文物，情节严重的，处五年以下有期徒刑或者拘役，并处罚金；情节特别严重的，处五年以上十年以下有期徒刑，并处罚金。"},{"i":370,"n":"第三百二十七条","txt":"违反文物保护法规，国有博物馆、图书馆等单位将国家保护的文物藏品出售或者私自送给非国有单位或者个人的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役。"},{"i":371,"n":"第三百二十八条","txt":"盗掘具有历史、艺术、科学价值的古文化遗址、古墓葬的，处三年以上十年以下有期徒刑，并处罚金；情节较轻的，处三年以下有期徒刑、拘役或者管制，并处罚金；有下列情形之一的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产："},{"i":372,"n":"第三百二十九条","txt":"抢夺、窃取国家所有的档案的，处五年以下有期徒刑或者拘役。"},{"i":373,"n":"第三百三十条","txt":"违反传染病防治法的规定，有下列情形之一，引起甲类传染病以及依法确定采取甲类传染病预防、控制措施的传染病传播或者有传播严重危险的，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑："},{"i":374,"n":"第三百三十一条","txt":"从事实验、保藏、携带、运输传染病菌种、毒种的人员，违反国务院卫生行政部门的有关规定，造成传染病菌种、毒种扩散，后果严重的，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。"},{"i":375,"n":"第三百三十二条","txt":"违反国境卫生检疫规定，引起检疫传染病传播或者有传播严重危险的，处三年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":376,"n":"第三百三十三条","txt":"非法组织他人出卖血液的，处五年以下有期徒刑，并处罚金；以暴力、威胁方法强迫他人出卖血液的，处五年以上十年以下有期徒刑，并处罚金。"},{"i":377,"n":"第三百三十四条","txt":"非法采集、供应血液或者制作、供应血液制品，不符合国家规定的标准，足以危害人体健康的，处五年以下有期徒刑或者拘役，并处罚金；对人体健康造成严重危害的，处五年以上十年以下有期徒刑，并处罚金；造成特别严重后果的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。"},{"i":378,"n":"第三百三十四条","txt":"违反国家有关规定，非法采集我国人类遗传资源或者非法运送、邮寄、携带我国人类遗传资源材料出境，危害公众健康或者社会公共利益，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":379,"n":"第三百三十五条","txt":"医务人员由于严重不负责任，造成就诊人死亡或者严重损害就诊人身体健康的，处三年以下有期徒刑或者拘役。"},{"i":380,"n":"第三百三十六条","txt":"未取得医生执业资格的人非法行医，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；严重损害就诊人身体健康的，处三年以上十年以下有期徒刑，并处罚金；造成就诊人死亡的，处十年以上有期徒刑，并处罚金。"},{"i":381,"n":"第三百三十六条","txt":"将基因编辑、克隆的人类胚胎植入人体或者动物体内，或者将基因编辑、克隆的动物胚胎植入人体内，情节严重的，处三年以下有期徒刑或者拘役，并处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":382,"n":"第三百三十七条","txt":"违反有关动植物防疫、检疫的国家规定，引起重大动植物疫情的，或者有引起重大动植物疫情危险，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":383,"n":"第三百三十八条","txt":"违反国家规定，排放、倾倒或者处置有放射性的废物、含传染病病原体的废物、有毒物质或者其他有害物质，严重污染环境的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金；有下列情形之一的，处七年以上有期徒刑，并处罚金："},{"i":384,"n":"第三百三十九条","txt":"违反国家规定，将境外的固体废物进境倾倒、堆放、处置的，处五年以下有期徒刑或者拘役，并处罚金；造成重大环境污染事故，致使公私财产遭受重大损失或者严重危害人体健康的，处五年以上十年以下有期徒刑，并处罚金；后果特别严重的，处十年以上有期徒刑，并处罚金。"},{"i":385,"n":"第三百四十条","txt":"违反保护水产资源法规，在禁渔区、禁渔期或者使用禁用的工具、方法捕捞水产品，情节严重的，处三年以下有期徒刑、拘役、管制或者罚金。"},{"i":386,"n":"第三百四十一条","txt":"非法猎捕、杀害国家重点保护的珍贵、濒危野生动物的，或者非法收购、运输、出售国家重点保护的珍贵、濒危野生动物及其制品的，处五年以下有期徒刑或者拘役，并处罚金；情节严重的，处五年以上十年以下有期徒刑，并处罚金；情节特别严重的，处十年以上有期徒刑，并处罚金或者没收财产。"},{"i":387,"n":"第三百四十二条","txt":"违反土地管理法规，非法占用耕地、林地等农用地，改变被占用土地用途，数量较大，造成耕地、林地等农用地大量毁坏的，处五年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":388,"n":"第三百四十二条","txt":"违反自然保护地管理法规，在国家公园、国家级自然保护区进行开垦、开发活动或者修建建筑物，造成严重后果或者有其他恶劣情节的，处五年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":389,"n":"第三百四十三条","txt":"违反矿产资源法的规定，未取得采矿许可证擅自采矿，擅自进入国家规划矿区、对国民经济具有重要价值的矿区和他人矿区范围采矿，或者擅自开采国家规定实行保护性开采的特定矿种，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":390,"n":"第三百四十四条","txt":"违反国家规定，非法采伐、毁坏珍贵树木或者国家重点保护的其他植物的，或者非法收购、运输、加工、出售珍贵树木或者国家重点保护的其他植物及其制品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":391,"n":"第三百四十四条","txt":"违反国家规定，非法引进、释放或者丢弃外来入侵物种，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":392,"n":"第三百四十五条","txt":"盗伐森林或者其他林木，数量较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数量巨大的，处三年以上七年以下有期徒刑，并处罚金；数量特别巨大的，处七年以上有期徒刑，并处罚金。"},{"i":393,"n":"第三百四十六条","txt":"单位犯本节第三百三十八条至第三百四十五条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本节各该条的规定处罚。"},{"i":394,"n":"第三百四十七条","txt":"走私、贩卖、运输、制造毒品，无论数量多少，都应当追究刑事责任，予以刑事处罚。"},{"i":395,"n":"第三百四十八条","txt":"非法持有鸦片一千克以上、海洛因或者甲基苯丙胺五十克以上或者其他毒品数量大的，处七年以上有期徒刑或者无期徒刑，并处罚金；非法持有鸦片二百克以上不满一千克、海洛因或者甲基苯丙胺十克以上不满五十克或者其他毒品数量较大的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":396,"n":"第三百四十九条","txt":"包庇走私、贩卖、运输、制造毒品的犯罪分子的，为犯罪分子窝藏、转移、隐瞒毒品或者犯罪所得的财物的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上十年以下有期徒刑。"},{"i":397,"n":"第三百五十条","txt":"违反国家规定，非法生产、买卖、运输醋酸酐、乙醚、三氯甲烷或者其他用于制造毒品的原料、配剂，或者携带上述物品进出境，情节较重的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金；情节特别严重的，处七年以上有期徒刑，并处罚金或者没收财产。"},{"i":398,"n":"第三百五十一条","txt":"非法种植罂粟、大麻等毒品原植物的，一律强制铲除。有下列情形之一的，处五年以下有期徒刑、拘役或者管制，并处罚金："},{"i":399,"n":"第三百五十二条","txt":"非法买卖、运输、携带、持有未经灭活的罂粟等毒品原植物种子或者幼苗，数量较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。"},{"i":400,"n":"第三百五十三条","txt":"引诱、教唆、欺骗他人吸食、注射毒品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":401,"n":"第三百五十四条","txt":"容留他人吸食、注射毒品的，处三年以下有期徒刑、拘役或者管制，并处罚金。"},{"i":402,"n":"第三百五十五条","txt":"依法从事生产、运输、管理、使用国家管制的麻醉药品、精神药品的人员，违反国家规定，向吸食、注射毒品的人提供国家规定管制的能够使人形成瘾癖的麻醉药品、精神药品的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。向走私、贩卖毒品的犯罪分子或者以牟利为目的，向吸食、注射毒品的人提供国家规定管制的能够使人形成瘾癖的麻醉药品、精神药品的，依照本法第三百四十七条的规定定罪处罚。"},{"i":403,"n":"第三百五十五条","txt":"引诱、教唆、欺骗运动员使用兴奋剂参加国内、国际重大体育竞赛，或者明知运动员参加上述竞赛而向其提供兴奋剂，情节严重的，处三年以下有期徒刑或者拘役，并处罚金。"},{"i":404,"n":"第三百五十六条","txt":"因走私、贩卖、运输、制造、非法持有毒品罪被判过刑，又犯本节规定之罪的，从重处罚。"},{"i":405,"n":"第三百五十七条","txt":"本法所称的毒品，是指鸦片、海洛因、甲基苯丙胺（冰毒）、吗啡、大麻、可卡因以及国家规定管制的其他能够使人形成瘾癖的麻醉药品和精神药品。"},{"i":406,"n":"第三百五十八条","txt":"组织、强迫他人卖淫的，处五年以上十年以下有期徒刑，并处罚金；情节严重的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。"},{"i":407,"n":"第三百五十九条","txt":"引诱、容留、介绍他人卖淫的，处五年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金。"},{"i":408,"n":"第三百六十条","txt":"明知自己患有梅毒、淋病等严重性病卖淫、嫖娼的，处五年以下有期徒刑、拘役或者管制，并处罚金。"},{"i":409,"n":"第三百六十一条","txt":"旅馆业、饮食服务业、文化娱乐业、出租汽车业等单位的人员，利用本单位的条件，组织、强迫、引诱、容留、介绍他人卖淫的，依照本法第三百五十八条、第三百五十九条的规定定罪处罚。"},{"i":410,"n":"第三百六十二条","txt":"旅馆业、饮食服务业、文化娱乐业、出租汽车业等单位的人员，在公安机关查处卖淫、嫖娼活动时，为违法犯罪分子通风报信，情节严重的，依照本法第三百一十条的规定定罪处罚。"},{"i":411,"n":"第三百六十三条","txt":"以牟利为目的，制作、复制、出版、贩卖、传播淫秽物品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金；情节特别严重的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。"},{"i":412,"n":"第三百六十四条","txt":"传播淫秽的书刊、影片、音像、图片或者其他淫秽物品，情节严重的，处二年以下有期徒刑、拘役或者管制。"},{"i":413,"n":"第三百六十五条","txt":"组织进行淫秽表演的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。"},{"i":414,"n":"第三百六十六条","txt":"单位犯本节第三百六十三条、第三百六十四条、第三百六十五条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该条的规定处罚。"},{"i":415,"n":"第三百六十七条","txt":"本法所称淫秽物品，是指具体描绘性行为或者露骨宣扬色情的诲淫性的书刊、影片、录像带、录音带、图片及其他淫秽物品。"},{"i":416,"n":"第三百六十八条","txt":"以暴力、威胁方法阻碍军人依法执行职务的，处三年以下有期徒刑、拘役、管制或者罚金。"},{"i":417,"n":"第三百六十九条","txt":"破坏武器装备、军事设施、军事通信的，处三年以下有期徒刑、拘役或者管制；破坏重要武器装备、军事设施、军事通信的，处三年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑、无期徒刑或者死刑。"},{"i":418,"n":"第三百七十条","txt":"明知是不合格的武器装备、军事设施而提供给武装部队的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑、无期徒刑或者死刑。"},{"i":419,"n":"第三百七十一条","txt":"聚众冲击军事禁区，严重扰乱军事禁区秩序的，对首要分子，处五年以上十年以下有期徒刑；对其他积极参加的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。"},{"i":420,"n":"第三百七十二条","txt":"冒充军人招摇撞骗的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上十年以下有期徒刑。"},{"i":421,"n":"第三百七十三条","txt":"煽动军人逃离部队或者明知是逃离部队的军人而雇用，情节严重的，处三年以下有期徒刑、拘役或者管制。"},{"i":422,"n":"第三百七十四条","txt":"在征兵工作中徇私舞弊，接送不合格兵员，情节严重的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。"},{"i":423,"n":"第三百七十五条","txt":"伪造、变造、买卖或者盗窃、抢夺武装部队公文、证件、印章的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上十年以下有期徒刑。"},{"i":424,"n":"第三百七十六条","txt":"预备役人员战时拒绝、逃避征召或者军事训练，情节严重的，处三年以下有期徒刑或者拘役。"},{"i":425,"n":"第三百七十七条","txt":"战时故意向武装部队提供虚假敌情，造成严重后果的，处三年以上十年以下有期徒刑；造成特别严重后果的，处十年以上有期徒刑或者无期徒刑。"},{"i":426,"n":"第三百七十八条","txt":"战时造谣惑众，扰乱军心的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上十年以下有期徒刑。"},{"i":427,"n":"第三百七十九条","txt":"战时明知是逃离部队的军人而为其提供隐蔽处所、财物，情节严重的，处三年以下有期徒刑或者拘役。"},{"i":428,"n":"第三百八十条","txt":"战时拒绝或者故意延误军事订货，情节严重的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役；造成严重后果的，处五年以上有期徒刑。"},{"i":429,"n":"第三百八十一条","txt":"战时拒绝军事征收、征用，情节严重的，处三年以下有期徒刑或者拘役。"},{"i":430,"n":"第三百八十二条","txt":"国家工作人员利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有公共财物的，是贪污罪。"},{"i":431,"n":"第三百八十三条","txt":"对犯贪污罪的，根据情节轻重，分别依照下列规定处罚："},{"i":432,"n":"第三百八十四条","txt":"国家工作人员利用职务上的便利，挪用公款归个人使用，进行非法活动的，或者挪用公款数额较大、进行营利活动的，或者挪用公款数额较大、超过三个月未还的，是挪用公款罪，处五年以下有期徒刑或者拘役；情节严重的，处五年以上有期徒刑。挪用公款数额巨大不退还的，处十年以上有期徒刑或者无期徒刑。"},{"i":433,"n":"第三百八十五条","txt":"国家工作人员利用职务上的便利，索取他人财物的，或者非法收受他人财物，为他人谋取利益的，是受贿罪。"},{"i":434,"n":"第三百八十六条","txt":"对犯受贿罪的，根据受贿所得数额及情节，依照本法第三百八十三条的规定处罚。索贿的从重处罚。"},{"i":435,"n":"第三百八十七条","txt":"国家机关、国有公司、企业、事业单位、人民团体，索取、非法收受他人财物，为他人谋取利益，情节严重的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。"},{"i":436,"n":"第三百八十八条","txt":"国家工作人员利用本人职权或者地位形成的便利条件，通过其他国家工作人员职务上的行为，为请托人谋取不正当利益，索取请托人财物或者收受请托人财物的，以受贿论处。"},{"i":437,"n":"第三百八十八条","txt":"国家工作人员的近亲属或者其他与该国家工作人员关系密切的人，通过该国家工作人员职务上的行为，或者利用该国家工作人员职权或者地位形成的便利条件，通过其他国家工作人员职务上的行为，为请托人谋取不正当利益，索取请托人财物或者收受请托人财物，数额较大或者有其他较重情节的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大或者有其他严重情节的，处三年以上七年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处七年以上有期徒刑，并处罚金或者没收财产。"},{"i":438,"n":"第三百八十九条","txt":"为谋取不正当利益，给予国家工作人员以财物的，是行贿罪。"},{"i":439,"n":"第三百九十条","txt":"对犯行贿罪的，处五年以下有期徒刑或者拘役，并处罚金；因行贿谋取不正当利益，情节严重的，或者使国家利益遭受重大损失的，处五年以上十年以下有期徒刑，并处罚金；情节特别严重的，或者使国家利益遭受特别重大损失的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。"},{"i":440,"n":"第三百九十条","txt":"为谋取不正当利益，向国家工作人员的近亲属或者其他与该国家工作人员关系密切的人，或者向离职的国家工作人员或者其近亲属以及其他与其关系密切的人行贿的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，或者使国家利益遭受重大损失的，处三年以上七年以下有期徒刑，并处罚金；情节特别严重的，或者使国家利益遭受特别重大损失的，处七年以上十年以下有期徒刑，并处罚金。"},{"i":441,"n":"第三百九十一条","txt":"为谋取不正当利益，给予国家机关、国有公司、企业、事业单位、人民团体以财物的，或者在经济往来中，违反国家规定，给予各种名义的回扣、手续费的，处三年以下有期徒刑或者拘役，并处罚金。"},{"i":442,"n":"第三百九十二条","txt":"向国家工作人员介绍贿赂，情节严重的，处三年以下有期徒刑或者拘役，并处罚金。"},{"i":443,"n":"第三百九十三条","txt":"单位为谋取不正当利益而行贿，或者违反国家规定，给予国家工作人员以回扣、手续费，情节严重的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，并处罚金。因行贿取得的违法所得归个人所有的，依照本法第三百八十九条、第三百九十条的规定定罪处罚。"},{"i":444,"n":"第三百九十四条","txt":"国家工作人员在国内公务活动或者对外交往中接受礼物，依照国家规定应当交公而不交公，数额较大的，依照本法第三百八十二条、第三百八十三条的规定定罪处罚。"},{"i":445,"n":"第三百九十五条","txt":"国家工作人员的财产、支出明显超过合法收入，差额巨大的，可以责令该国家工作人员说明来源，不能说明来源的，差额部分以非法所得论，处五年以下有期徒刑或者拘役；差额特别巨大的，处五年以上十年以下有期徒刑。财产的差额部分予以追缴。"},{"i":446,"n":"第三百九十六条","txt":"国家机关、国有公司、企业、事业单位、人民团体，违反国家规定，以单位名义将国有资产集体私分给个人，数额较大的，对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役，并处或者单处罚金；数额巨大的，处三年以上七年以下有期徒刑，并处罚金。"},{"i":447,"n":"第三百九十七条","txt":"国家机关工作人员滥用职权或者玩忽职守，致使公共财产、国家和人民利益遭受重大损失的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。本法另有规定的，依照规定。"},{"i":448,"n":"第三百九十八条","txt":"国家机关工作人员违反保守国家秘密法的规定，故意或者过失泄露国家秘密，情节严重的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。"},{"i":449,"n":"第三百九十九条","txt":"司法工作人员徇私枉法、徇情枉法，对明知是无罪的人而使他受追诉、对明知是有罪的人而故意包庇不使他受追诉，或者在刑事审判活动中故意违背事实和法律作枉法裁判的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑。"},{"i":450,"n":"第三百九十九条","txt":"依法承担仲裁职责的人员，在仲裁活动中故意违背事实和法律作枉法裁决，情节严重的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。"},{"i":451,"n":"第四百条","txt":"司法工作人员私放在押的犯罪嫌疑人、被告人或者罪犯的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑。"},{"i":452,"n":"第四百零一条","txt":"司法工作人员徇私舞弊，对不符合减刑、假释、暂予监外执行条件的罪犯，予以减刑、假释或者暂予监外执行的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。"},{"i":453,"n":"第四百零二条","txt":"行政执法人员徇私舞弊，对依法应当移交司法机关追究刑事责任的不移交，情节严重的，处三年以下有期徒刑或者拘役；造成严重后果的，处三年以上七年以下有期徒刑。"},{"i":454,"n":"第四百零三条","txt":"国家有关主管部门的国家机关工作人员，徇私舞弊，滥用职权，对不符合法律规定条件的公司设立、登记申请或者股票、债券发行、上市申请，予以批准或者登记，致使公共财产、国家和人民利益遭受重大损失的，处五年以下有期徒刑或者拘役。"},{"i":455,"n":"第四百零四条","txt":"税务机关的工作人员徇私舞弊，不征或者少征应征税款，致使国家税收遭受重大损失的，处五年以下有期徒刑或者拘役；造成特别重大损失的，处五年以上有期徒刑。"},{"i":456,"n":"第四百零五条","txt":"税务机关的工作人员违反法律、行政法规的规定，在办理发售发票、抵扣税款、出口退税工作中，徇私舞弊，致使国家利益遭受重大损失的，处五年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处五年以上有期徒刑。"},{"i":457,"n":"第四百零六条","txt":"国家机关工作人员在签订、履行合同过程中，因严重不负责任被诈骗，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑。"},{"i":458,"n":"第四百零七条","txt":"林业主管部门的工作人员违反森林法的规定，超过批准的年采伐限额发放林木采伐许可证或者违反规定滥发林木采伐许可证，情节严重，致使森林遭受严重破坏的，处三年以下有期徒刑或者拘役。"},{"i":459,"n":"第四百零八条","txt":"负有环境保护监督管理职责的国家机关工作人员严重不负责任，导致发生重大环境污染事故，致使公私财产遭受重大损失或者造成人身伤亡的严重后果的，处三年以下有期徒刑或者拘役。"},{"i":460,"n":"第四百零八条","txt":"负有食品药品安全监督管理职责的国家机关工作人员，滥用职权或者玩忽职守，有下列情形之一，造成严重后果或者有其他严重情节的，处五年以下有期徒刑或者拘役；造成特别严重后果或者有其他特别严重情节的，处五年以上十年以下有期徒刑："},{"i":461,"n":"第四百零九条","txt":"从事传染病防治的政府卫生行政部门的工作人员严重不负责任，导致传染病传播或者流行，情节严重的，处三年以下有期徒刑或者拘役。"},{"i":462,"n":"第四百一十条","txt":"国家机关工作人员徇私舞弊，违反土地管理法规，滥用职权，非法批准征收、征用、占用土地，或者非法低价出让国有土地使用权，情节严重的，处三年以下有期徒刑或者拘役；致使国家或者集体利益遭受特别重大损失的，处三年以上七年以下有期徒刑。"},{"i":463,"n":"第四百一十一条","txt":"海关工作人员徇私舞弊，放纵走私，情节严重的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上有期徒刑。"},{"i":464,"n":"第四百一十二条","txt":"国家商检部门、商检机构的工作人员徇私舞弊，伪造检验结果的，处五年以下有期徒刑或者拘役；造成严重后果的，处五年以上十年以下有期徒刑。"},{"i":465,"n":"第四百一十三条","txt":"动植物检疫机关的检疫人员徇私舞弊，伪造检疫结果的，处五年以下有期徒刑或者拘役；造成严重后果的，处五年以上十年以下有期徒刑。"},{"i":466,"n":"第四百一十四条","txt":"对生产、销售伪劣商品犯罪行为负有追究责任的国家机关工作人员，徇私舞弊，不履行法律规定的追究职责，情节严重的，处五年以下有期徒刑或者拘役。"},{"i":467,"n":"第四百一十五条","txt":"负责办理护照、签证以及其他出入境证件的国家机关工作人员，对明知是企图偷越国（边）境的人员，予以办理出入境证件的，或者边防、海关等国家机关工作人员，对明知是偷越国（边）境的人员，予以放行的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。"},{"i":468,"n":"第四百一十六条","txt":"对被拐卖、绑架的妇女、儿童负有解救职责的国家机关工作人员，接到被拐卖、绑架的妇女、儿童及其家属的解救要求或者接到其他人的举报，而对被拐卖、绑架的妇女、儿童不进行解救，造成严重后果的，处五年以下有期徒刑或者拘役。"},{"i":469,"n":"第四百一十七条","txt":"有查禁犯罪活动职责的国家机关工作人员，向犯罪分子通风报信、提供便利，帮助犯罪分子逃避处罚的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上十年以下有期徒刑。"},{"i":470,"n":"第四百一十八条","txt":"国家机关工作人员在招收公务员、学生工作中徇私舞弊，情节严重的，处三年以下有期徒刑或者拘役。"},{"i":471,"n":"第四百一十九条","txt":"国家机关工作人员严重不负责任，造成珍贵文物损毁或者流失，后果严重的，处三年以下有期徒刑或者拘役。"},{"i":472,"n":"第四百二十条","txt":"军人违反职责，危害国家军事利益，依照法律应当受刑罚处罚的行为，是军人违反职责罪。"},{"i":473,"n":"第四百二十一条","txt":"战时违抗命令，对作战造成危害的，处三年以上十年以下有期徒刑；致使战斗、战役遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。"},{"i":474,"n":"第四百二十二条","txt":"故意隐瞒、谎报军情或者拒传、假传军令，对作战造成危害的，处三年以上十年以下有期徒刑；致使战斗、战役遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。"},{"i":475,"n":"第四百二十三条","txt":"在战场上贪生怕死，自动放下武器投降敌人的，处三年以上十年以下有期徒刑；情节严重的，处十年以上有期徒刑或者无期徒刑。"},{"i":476,"n":"第四百二十四条","txt":"战时临阵脱逃的，处三年以下有期徒刑；情节严重的，处三年以上十年以下有期徒刑；致使战斗、战役遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。"},{"i":477,"n":"第四百二十五条","txt":"指挥人员和值班、值勤人员擅离职守或者玩忽职守，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。"},{"i":478,"n":"第四百二十六条","txt":"以暴力、威胁方法，阻碍指挥人员或者值班、值勤人员执行职务的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑。战时从重处罚。"},{"i":479,"n":"第四百二十七条","txt":"滥用职权，指使部属进行违反职责的活动，造成严重后果的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上十年以下有期徒刑。"},{"i":480,"n":"第四百二十八条","txt":"指挥人员违抗命令，临阵畏缩，作战消极，造成严重后果的，处五年以下有期徒刑；致使战斗、战役遭受重大损失或者有其他特别严重情节的，处五年以上有期徒刑。"},{"i":481,"n":"第四百二十九条","txt":"在战场上明知友邻部队处境危急请求救援，能救援而不救援，致使友邻部队遭受重大损失的，对指挥人员，处五年以下有期徒刑。"},{"i":482,"n":"第四百三十条","txt":"在履行公务期间，擅离岗位，叛逃境外或者在境外叛逃，危害国家军事利益的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上有期徒刑。"},{"i":483,"n":"第四百三十一条","txt":"以窃取、刺探、收买方法，非法获取军事秘密的，处五年以下有期徒刑；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑。"},{"i":484,"n":"第四百三十二条","txt":"违反保守国家秘密法规，故意或者过失泄露军事秘密，情节严重的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上十年以下有期徒刑。"},{"i":485,"n":"第四百三十三条","txt":"战时造谣惑众，动摇军心的，处三年以下有期徒刑；情节严重的，处三年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑。"},{"i":486,"n":"第四百三十四条","txt":"战时自伤身体，逃避军事义务的，处三年以下有期徒刑；情节严重的，处三年以上七年以下有期徒刑。"},{"i":487,"n":"第四百三十五条","txt":"违反兵役法规，逃离部队，情节严重的，处三年以下有期徒刑或者拘役。"},{"i":488,"n":"第四百三十六条","txt":"违反武器装备使用规定，情节严重，因而发生责任事故，致人重伤、死亡或者造成其他严重后果的，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。"},{"i":489,"n":"第四百三十七条","txt":"违反武器装备管理规定，擅自改变武器装备的编配用途，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。"},{"i":490,"n":"第四百三十八条","txt":"盗窃、抢夺武器装备或者军用物资的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑、无期徒刑或者死刑。"},{"i":491,"n":"第四百三十九条","txt":"非法出卖、转让军队武器装备的，处三年以上十年以下有期徒刑；出卖、转让大量武器装备或者有其他特别严重情节的，处十年以上有期徒刑、无期徒刑或者死刑。"},{"i":492,"n":"第四百四十条","txt":"违抗命令，遗弃武器装备的，处五年以下有期徒刑或者拘役；遗弃重要或者大量武器装备的，或者有其他严重情节的，处五年以上有期徒刑。"},{"i":493,"n":"第四百四十一条","txt":"遗失武器装备，不及时报告或者有其他严重情节的，处三年以下有期徒刑或者拘役。"},{"i":494,"n":"第四百四十二条","txt":"违反规定，擅自出卖、转让军队房地产，情节严重的，对直接责任人员，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上十年以下有期徒刑。"},{"i":495,"n":"第四百四十三条","txt":"滥用职权，虐待部属，情节恶劣，致人重伤或者造成其他严重后果的，处五年以下有期徒刑或者拘役；致人死亡的，处五年以上有期徒刑。"},{"i":496,"n":"第四百四十四条","txt":"在战场上故意遗弃伤病军人，情节恶劣的，对直接责任人员，处五年以下有期徒刑。"},{"i":497,"n":"第四百四十五条","txt":"战时在救护治疗职位上，有条件救治而拒不救治危重伤病军人的，处五年以下有期徒刑或者拘役；造成伤病军人重残、死亡或者有其他严重情节的，处五年以上十年以下有期徒刑。"},{"i":498,"n":"第四百四十六条","txt":"战时在军事行动地区，残害无辜居民或者掠夺无辜居民财物的，处五年以下有期徒刑；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑、无期徒刑或者死刑。"},{"i":499,"n":"第四百四十七条","txt":"私放俘虏的，处五年以下有期徒刑；私放重要俘虏、私放俘虏多人或者有其他严重情节的，处五年以上有期徒刑。"},{"i":500,"n":"第四百四十八条","txt":"虐待俘虏，情节恶劣的，处三年以下有期徒刑。"},{"i":501,"n":"第四百四十九条","txt":"在战时，对被判处三年以下有期徒刑没有现实危险宣告缓刑的犯罪军人，允许其戴罪立功，确有立功表现时，可以撤销原判刑罚，不以犯罪论处。"},{"i":502,"n":"第四百五十条","txt":"本章适用于中国人民解放军的现役军官、文职干部、士兵及具有军籍的学员和中国人民武装警察部队的现役警官、文职干部、士兵及具有军籍的学员以及文职人员、执行军事任务的预备役人员和其他人员。"},{"i":503,"n":"第四百五十一条","txt":"本章所称战时，是指国家宣布进入战争状态、部队受领作战任务或者遭敌突然袭击时。"},{"i":504,"n":"第四百五十二条","txt":"本法自1997年10月1日起施行。"}],"fanyouzuzhifanzuifa":[{"i":1,"n":"第一条","txt":"为了预防和惩治有组织犯罪，加强和规范反有组织犯罪工作，维护国家安全、社会秩序、经济秩序，保护公民和组织的合法权益，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称有组织犯罪，是指《中华人民共和国刑法》第二百九十四条规定的组织、领导、参加黑社会性质组织犯罪，以及黑社会性质组织、恶势力组织实施的犯罪。"},{"i":3,"n":"第三条","txt":"反有组织犯罪工作应当坚持总体国家安全观，综合运用法律、经济、科技、文化、教育等手段，建立健全反有组织犯罪工作机制和有组织犯罪预防治理体系。"},{"i":4,"n":"第四条","txt":"反有组织犯罪工作应当坚持专门工作与群众路线相结合，坚持专项治理与系统治理相结合，坚持与反腐败相结合，坚持与加强基层组织建设相结合，惩防并举、标本兼治。"},{"i":5,"n":"第五条","txt":"反有组织犯罪工作应当依法进行，尊重和保障人权，维护公民和组织的合法权益。"},{"i":6,"n":"第六条","txt":"监察机关、人民法院、人民检察院、公安机关、司法行政机关以及其他有关国家机关，应当根据分工，互相配合，互相制约，依法做好反有组织犯罪工作。"},{"i":7,"n":"第七条","txt":"任何单位和个人都有协助、配合有关部门开展反有组织犯罪工作的义务。"},{"i":8,"n":"第八条","txt":"国家鼓励单位和个人举报有组织犯罪。"},{"i":9,"n":"第九条","txt":"各级人民政府和有关部门应当依法组织开展有组织犯罪预防和治理工作，将有组织犯罪预防和治理工作纳入考评体系。"},{"i":10,"n":"第十条","txt":"承担有组织犯罪预防和治理职责的部门应当开展反有组织犯罪宣传教育，增强公民的反有组织犯罪意识和能力。"},{"i":11,"n":"第十一条","txt":"教育行政部门、学校应当会同有关部门建立防范有组织犯罪侵害校园工作机制，加强反有组织犯罪宣传教育，增强学生防范有组织犯罪的意识，教育引导学生自觉抵制有组织犯罪，防范有组织犯罪的侵害。"},{"i":12,"n":"第十二条","txt":"民政部门应当会同监察机关、公安机关等有关部门，对村民委员会、居民委员会成员候选人资格进行审查，发现因实施有组织犯罪受过刑事处罚的，应当依照有关规定及时作出处理；发现有组织犯罪线索的，应当及时向公安机关报告。"},{"i":13,"n":"第十三条","txt":"市场监管、金融监管、自然资源、交通运输等行业主管部门应当会同公安机关，建立健全行业有组织犯罪预防和治理长效机制，对相关行业领域内有组织犯罪情况进行监测分析，对有组织犯罪易发的行业领域加强监督管理。"},{"i":14,"n":"第十四条","txt":"监察机关、人民法院、人民检察院、公安机关在办理案件中发现行业主管部门有组织犯罪预防和治理工作存在问题的，可以书面向相关行业主管部门提出意见建议。相关行业主管部门应当及时处理并书面反馈。"},{"i":15,"n":"第十五条","txt":"公安机关可以会同有关部门根据本地有组织犯罪情况，确定预防和治理的重点区域、行业领域或者场所。"},{"i":16,"n":"第十六条","txt":"电信业务经营者、互联网服务提供者应当依法履行网络信息安全管理义务，采取安全技术防范措施，防止含有宣扬、诱导有组织犯罪内容的信息传播；发现含有宣扬、诱导有组织犯罪内容的信息的，应当立即停止传输，采取消除等处置措施，保存相关记录，并向公安机关或者有关部门报告，依法为公安机关侦查有组织犯罪提供技术支持和协助。"},{"i":17,"n":"第十七条","txt":"国务院反洗钱行政主管部门、国务院其他有关部门、机构应当督促金融机构和特定非金融机构履行反洗钱义务。发现与有组织犯罪有关的可疑交易活动的，有关主管部门可以依法进行调查，经调查不能排除洗钱嫌疑的，应当及时向公安机关报案。"},{"i":18,"n":"第十八条","txt":"监狱、看守所、社区矫正机构对有组织犯罪的罪犯，应当采取有针对性的监管、教育、矫正措施。"},{"i":19,"n":"第十九条","txt":"对因组织、领导黑社会性质组织被判处刑罚的人员，设区的市级以上公安机关可以决定其自刑罚执行完毕之日起，按照国家有关规定向公安机关报告个人财产及日常活动。报告期限不超过五年。"},{"i":20,"n":"第二十条","txt":"曾被判处刑罚的黑社会性质组织的组织者、领导者或者恶势力组织的首要分子开办企业或者在企业中担任高级管理人员的，相关行业主管部门应当依法审查，对其经营活动加强监督管理。"},{"i":21,"n":"第二十一条","txt":"移民管理、海关、海警等部门应当会同公安机关严密防范境外的黑社会组织入境渗透、发展、实施违法犯罪活动。"},{"i":22,"n":"第二十二条","txt":"办理有组织犯罪案件，应当以事实为根据，以法律为准绳，坚持宽严相济。"},{"i":23,"n":"第二十三条","txt":"利用网络实施的犯罪，符合本法第二条规定的，应当认定为有组织犯罪。"},{"i":24,"n":"第二十四条","txt":"公安机关应当依法运用现代信息技术，建立有组织犯罪线索收集和研判机制，分级分类进行处置。"},{"i":25,"n":"第二十五条","txt":"有关国家机关在履行职责时发现有组织犯罪线索，或者接到对有组织犯罪的举报的，应当及时移送公安机关等主管机关依法处理。"},{"i":26,"n":"第二十六条","txt":"公安机关核查有组织犯罪线索，可以按照国家有关规定采取调查措施。公安机关向有关单位和个人收集、调取相关信息和材料的，有关单位和个人应当如实提供。"},{"i":27,"n":"第二十七条","txt":"公安机关核查有组织犯罪线索，经县级以上公安机关负责人批准，可以查询嫌疑人员的存款、汇款、债券、股票、基金份额等财产信息。"},{"i":28,"n":"第二十八条","txt":"公安机关核查有组织犯罪线索，发现犯罪事实或者犯罪嫌疑人的，应当依照《中华人民共和国刑事诉讼法》的规定立案侦查。"},{"i":29,"n":"第二十九条","txt":"公安机关办理有组织犯罪案件，可以依照《中华人民共和国出境入境管理法》的规定，决定对犯罪嫌疑人采取限制出境措施，通知移民管理机构执行。"},{"i":30,"n":"第三十条","txt":"对有组织犯罪案件的犯罪嫌疑人、被告人，根据办理案件和维护监管秩序的需要，可以采取异地羁押、分别羁押或者单独羁押等措施。采取异地羁押措施的，应当依法通知犯罪嫌疑人、被告人的家属和辩护人。"},{"i":31,"n":"第三十一条","txt":"公安机关在立案后，根据侦查犯罪的需要，依照《中华人民共和国刑事诉讼法》的规定，可以采取技术侦查措施、实施控制下交付或者由有关人员隐匿身份进行侦查。"},{"i":32,"n":"第三十二条","txt":"犯罪嫌疑人、被告人检举、揭发重大犯罪的其他共同犯罪人或者提供侦破重大案件的重要线索或者证据，同案处理可能导致其本人或者近亲属有人身危险的，可以分案处理。"},{"i":33,"n":"第三十三条","txt":"犯罪嫌疑人、被告人积极配合有组织犯罪案件的侦查、起诉、审判等工作，有下列情形之一的，可以依法从宽处罚，但对有组织犯罪的组织者、领导者应当严格适用："},{"i":34,"n":"第三十四条","txt":"对黑社会性质组织的组织者、领导者，应当依法并处没收财产。对其他组织成员，根据其在犯罪组织中的地位、作用以及所参与违法犯罪活动的次数、性质、违法所得数额、造成的损失等，可以依法并处罚金或者没收财产。"},{"i":35,"n":"第三十五条","txt":"对有组织犯罪的罪犯，执行机关应当依法从严管理。"},{"i":36,"n":"第三十六条","txt":"对被判处十年以上有期徒刑、无期徒刑、死刑缓期二年执行的黑社会性质组织的组织者、领导者或者恶势力组织的首要分子减刑的，执行机关应当依法提出减刑建议，报经省、自治区、直辖市监狱管理机关复核后，提请人民法院裁定。"},{"i":37,"n":"第三十七条","txt":"人民法院审理黑社会性质组织犯罪罪犯的减刑、假释案件，应当通知人民检察院、执行机关参加审理，并通知被报请减刑、假释的罪犯参加，听取其意见。"},{"i":38,"n":"第三十八条","txt":"执行机关提出减刑、假释建议以及人民法院审理减刑、假释案件，应当充分考虑罪犯履行生效裁判中财产性判项、配合处置涉案财产等情况。"},{"i":39,"n":"第三十九条","txt":"办理有组织犯罪案件中发现的可用以证明犯罪嫌疑人、被告人有罪或者无罪的各种财物、文件，应当依法查封、扣押。"},{"i":40,"n":"第四十条","txt":"公安机关、人民检察院、人民法院根据办理有组织犯罪案件的需要，可以全面调查涉嫌有组织犯罪的组织及其成员的财产状况。"},{"i":41,"n":"第四十一条","txt":"查封、扣押、冻结、处置涉案财物，应当严格依照法定条件和程序进行，依法保护公民和组织的合法财产权益，严格区分违法所得与合法财产、本人财产与其家属的财产，减少对企业正常经营活动的不利影响。不得查封、扣押、冻结与案件无关的财物。经查明确实与案件无关的财物，应当在三日以内解除查封、扣押、冻结，予以退还。对被害人的合法财产，应当及时返还。"},{"i":42,"n":"第四十二条","txt":"公安机关可以向反洗钱行政主管部门查询与有组织犯罪相关的信息数据，提请协查与有组织犯罪相关的可疑交易活动，反洗钱行政主管部门应当予以配合并及时回复。"},{"i":43,"n":"第四十三条","txt":"对下列财产，经县级以上公安机关、人民检察院或者人民法院主要负责人批准，可以依法先行出售、变现或者变卖、拍卖，所得价款由扣押、冻结机关保管，并及时告知犯罪嫌疑人、被告人或者其近亲属："},{"i":44,"n":"第四十四条","txt":"公安机关、人民检察院应当对涉案财产审查甄别。在移送审查起诉、提起公诉时，应当对涉案财产提出处理意见。"},{"i":45,"n":"第四十五条","txt":"有组织犯罪组织及其成员违法所得的一切财物及其孳息、收益，违禁品和供犯罪所用的本人财物，应当依法予以追缴、没收或者责令退赔。"},{"i":46,"n":"第四十六条","txt":"涉案财产符合下列情形之一的，应当依法予以追缴、没收："},{"i":47,"n":"第四十七条","txt":"黑社会性质组织犯罪案件的犯罪嫌疑人、被告人逃匿，在通缉一年后不能到案，或者犯罪嫌疑人、被告人死亡，依照《中华人民共和国刑法》规定应当追缴其违法所得及其他涉案财产的，依照《中华人民共和国刑事诉讼法》有关犯罪嫌疑人、被告人逃匿、死亡案件违法所得的没收程序的规定办理。"},{"i":48,"n":"第四十八条","txt":"监察机关、公安机关、人民检察院发现与有组织犯罪相关的洗钱以及掩饰、隐瞒犯罪所得、犯罪所得收益等犯罪的，应当依法查处。"},{"i":49,"n":"第四十九条","txt":"利害关系人对查封、扣押、冻结、处置涉案财物提出异议的，公安机关、人民检察院、人民法院应当及时予以核实，听取其意见，依法作出处理。"},{"i":50,"n":"第五十条","txt":"国家工作人员有下列行为的，应当全面调查，依法作出处理："},{"i":51,"n":"第五十一条","txt":"监察机关、人民法院、人民检察院、公安机关、司法行政机关应当加强协作配合，建立线索办理沟通机制，发现国家工作人员涉嫌本法第五十条规定的违法犯罪的线索，应当依法处理或者及时移送主管机关处理。"},{"i":52,"n":"第五十二条","txt":"依法查办有组织犯罪案件或者依照职责支持、协助查办有组织犯罪案件的国家工作人员，不得有下列行为："},{"i":53,"n":"第五十三条","txt":"有关机关接到对从事反有组织犯罪工作的执法、司法工作人员的举报后，应当依法处理，防止犯罪嫌疑人、被告人等利用举报干扰办案、打击报复。"},{"i":54,"n":"第五十四条","txt":"中华人民共和国根据缔结或者参加的国际条约，或者按照平等互惠原则，与其他国家、地区、国际组织开展反有组织犯罪合作。"},{"i":55,"n":"第五十五条","txt":"国务院有关部门根据国务院授权，代表中国政府与外国政府和有关国际组织开展反有组织犯罪情报信息交流和执法合作。"},{"i":56,"n":"第五十六条","txt":"涉及有组织犯罪的刑事司法协助、引渡，依照有关法律的规定办理。"},{"i":57,"n":"第五十七条","txt":"通过反有组织犯罪国际合作取得的材料可以在行政处罚、刑事诉讼中作为证据使用，但依据条约规定或者我方承诺不作为证据使用的除外。"},{"i":58,"n":"第五十八条","txt":"国家为反有组织犯罪工作提供必要的组织保障、制度保障和物质保障。"},{"i":59,"n":"第五十九条","txt":"公安机关和有关部门应当依照职责，建立健全反有组织犯罪专业力量，加强人才队伍建设和专业训练，提升反有组织犯罪工作能力。"},{"i":60,"n":"第六十条","txt":"国务院和县级以上地方各级人民政府应当按照事权划分，将反有组织犯罪工作经费列入本级财政预算。"},{"i":61,"n":"第六十一条","txt":"因举报、控告和制止有组织犯罪活动，在有组织犯罪案件中作证，本人或者其近亲属的人身安全面临危险的，公安机关、人民检察院、人民法院应当按照有关规定，采取下列一项或者多项保护措施："},{"i":62,"n":"第六十二条","txt":"采取本法第六十一条第三项、第四项规定的保护措施，由公安机关执行。根据本法第六十一条第五项规定，变更被保护人员身份的，由国务院公安部门批准和组织实施。"},{"i":63,"n":"第六十三条","txt":"实施有组织犯罪的人员配合侦查、起诉、审判等工作，对侦破案件或者查明案件事实起到重要作用的，可以参照证人保护的规定执行。"},{"i":64,"n":"第六十四条","txt":"对办理有组织犯罪案件的执法、司法工作人员及其近亲属，可以采取人身保护、禁止特定的人接触等保护措施。"},{"i":65,"n":"第六十五条","txt":"对因履行反有组织犯罪工作职责或者协助、配合有关部门开展反有组织犯罪工作导致伤残或者死亡的人员，按照国家有关规定给予相应的待遇。"},{"i":66,"n":"第六十六条","txt":"组织、领导、参加黑社会性质组织，国家机关工作人员包庇、纵容黑社会性质组织，以及黑社会性质组织、恶势力组织实施犯罪的，依法追究刑事责任。"},{"i":67,"n":"第六十七条","txt":"发展未成年人参加黑社会性质组织、境外的黑社会组织，教唆、诱骗未成年人实施有组织犯罪，或者实施有组织犯罪侵害未成年人合法权益的，依法从重追究刑事责任。"},{"i":68,"n":"第六十八条","txt":"对有组织犯罪的罪犯，人民法院可以依照《中华人民共和国刑法》有关从业禁止的规定，禁止其从事相关职业，并通报相关行业主管部门。"},{"i":69,"n":"第六十九条","txt":"有下列情形之一，尚不构成犯罪的，由公安机关处五日以上十日以下拘留，可以并处一万元以下罚款；情节较重的，处十日以上十五日以下拘留，并处一万元以上三万元以下罚款；有违法所得的，除依法应当返还被害人的以外，应当予以没收："},{"i":70,"n":"第七十条","txt":"违反本法第十九条规定，不按照公安机关的决定如实报告个人财产及日常活动的，由公安机关给予警告，并责令改正；拒不改正的，处五日以上十日以下拘留，并处三万元以下罚款。"},{"i":71,"n":"第七十一条","txt":"金融机构等相关单位未依照本法第二十七条规定协助公安机关采取紧急止付、临时冻结措施的，由公安机关责令改正；拒不改正的，由公安机关处五万元以上二十万元以下罚款，并对直接负责的主管人员和其他直接责任人员处五万元以下罚款；情节严重的，公安机关可以建议有关主管部门对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":72,"n":"第七十二条","txt":"电信业务经营者、互联网服务提供者有下列情形之一的，由有关主管部门责令改正；拒不改正或者情节严重的，由有关主管部门依照《中华人民共和国网络安全法》的有关规定给予处罚："},{"i":73,"n":"第七十三条","txt":"有关国家机关、行业主管部门拒不履行或者拖延履行反有组织犯罪法定职责，或者拒不配合反有组织犯罪调查取证，或者在其他工作中滥用反有组织犯罪工作有关措施的，由其上级机关责令改正；情节严重的，对负有责任的领导人员和直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":74,"n":"第七十四条","txt":"有关部门和单位、个人应当对在反有组织犯罪工作过程中知悉的国家秘密、商业秘密和个人隐私予以保密。违反规定泄露国家秘密、商业秘密和个人隐私的，依法追究法律责任。"},{"i":75,"n":"第七十五条","txt":"国家工作人员有本法第五十条、第五十二条规定的行为，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":76,"n":"第七十六条","txt":"有关单位和个人对依照本法作出的行政处罚和行政强制措施决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":77,"n":"第七十七条","txt":"本法自2022年5月1日起施行。"}],"fandianxinwangluozhapianfa":[{"i":1,"n":"第一条","txt":"为了预防、遏制和惩治电信网络诈骗活动，加强反电信网络诈骗工作，保护公民和组织的合法权益，维护社会稳定和国家安全，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称电信网络诈骗，是指以非法占有为目的，利用电信网络技术手段，通过远程、非接触等方式，诈骗公私财物的行为。"},{"i":3,"n":"第三条","txt":"打击治理在中华人民共和国境内实施的电信网络诈骗活动或者中华人民共和国公民在境外实施的电信网络诈骗活动，适用本法。"},{"i":4,"n":"第四条","txt":"反电信网络诈骗工作坚持以人民为中心，统筹发展和安全；坚持系统观念、法治思维，注重源头治理、综合治理；坚持齐抓共管、群防群治，全面落实打防管控各项措施，加强社会宣传教育防范；坚持精准防治，保障正常生产经营活动和群众生活便利。"},{"i":5,"n":"第五条","txt":"反电信网络诈骗工作应当依法进行，维护公民和组织的合法权益。"},{"i":6,"n":"第六条","txt":"国务院建立反电信网络诈骗工作机制，统筹协调打击治理工作。"},{"i":7,"n":"第七条","txt":"有关部门、单位在反电信网络诈骗工作中应当密切协作，实现跨行业、跨地域协同配合、快速联动，加强专业队伍建设，有效打击治理电信网络诈骗活动。"},{"i":8,"n":"第八条","txt":"各级人民政府和有关部门应当加强反电信网络诈骗宣传，普及相关法律和知识，提高公众对各类电信网络诈骗方式的防骗意识和识骗能力。"},{"i":9,"n":"第九条","txt":"电信业务经营者应当依法全面落实电话用户真实身份信息登记制度。"},{"i":10,"n":"第十条","txt":"办理电话卡不得超出国家有关规定限制的数量。"},{"i":11,"n":"第十一条","txt":"电信业务经营者对监测识别的涉诈异常电话卡用户应当重新进行实名核验，根据风险等级采取有区别的、相应的核验措施。对未按规定核验或者核验未通过的，电信业务经营者可以限制、暂停有关电话卡功能。"},{"i":12,"n":"第十二条","txt":"电信业务经营者建立物联网卡用户风险评估制度，评估未通过的，不得向其销售物联网卡；严格登记物联网卡用户身份信息；采取有效技术措施限定物联网卡开通功能、使用场景和适用设备。"},{"i":13,"n":"第十三条","txt":"电信业务经营者应当规范真实主叫号码传送和电信线路出租，对改号电话进行封堵拦截和溯源核查。"},{"i":14,"n":"第十四条","txt":"任何单位和个人不得非法制造、买卖、提供或者使用下列设备、软件："},{"i":15,"n":"第十五条","txt":"银行业金融机构、非银行支付机构为客户开立银行账户、支付账户及提供支付结算服务，和与客户业务关系存续期间，应当建立客户尽职调查制度，依法识别受益所有人，采取相应风险管理措施，防范银行账户、支付账户等被用于电信网络诈骗活动。"},{"i":16,"n":"第十六条","txt":"开立银行账户、支付账户不得超出国家有关规定限制的数量。"},{"i":17,"n":"第十七条","txt":"银行业金融机构、非银行支付机构应当建立开立企业账户异常情形的风险防控机制。金融、电信、市场监管、税务等有关部门建立开立企业账户相关信息共享查询系统，提供联网核查服务。"},{"i":18,"n":"第十八条","txt":"银行业金融机构、非银行支付机构应当对银行账户、支付账户及支付结算服务加强监测，建立完善符合电信网络诈骗活动特征的异常账户和可疑交易监测机制。"},{"i":19,"n":"第十九条","txt":"银行业金融机构、非银行支付机构应当按照国家有关规定，完整、准确传输直接提供商品或者服务的商户名称、收付款客户名称及账号等交易信息，保证交易信息的真实、完整和支付全流程中的一致性。"},{"i":20,"n":"第二十条","txt":"国务院公安部门会同有关部门建立完善电信网络诈骗涉案资金即时查询、紧急止付、快速冻结、及时解冻和资金返还制度，明确有关条件、程序和救济措施。"},{"i":21,"n":"第二十一条","txt":"电信业务经营者、互联网服务提供者为用户提供下列服务，在与用户签订协议或者确认提供服务时，应当依法要求用户提供真实身份信息，用户不提供真实身份信息的，不得提供服务："},{"i":22,"n":"第二十二条","txt":"互联网服务提供者对监测识别的涉诈异常账号应当重新核验，根据国家有关规定采取限制功能、暂停服务等处置措施。"},{"i":23,"n":"第二十三条","txt":"设立移动互联网应用程序应当按照国家有关规定向电信主管部门办理许可或者备案手续。"},{"i":24,"n":"第二十四条","txt":"提供域名解析、域名跳转、网址链接转换服务的，应当按照国家有关规定，核验域名注册、解析信息和互联网协议地址的真实性、准确性，规范域名跳转，记录并留存所提供相应服务的日志信息，支持实现对解析、跳转、转换记录的溯源。"},{"i":25,"n":"第二十五条","txt":"任何单位和个人不得为他人实施电信网络诈骗活动提供下列支持或者帮助："},{"i":26,"n":"第二十六条","txt":"公安机关办理电信网络诈骗案件依法调取证据的，互联网服务提供者应当及时提供技术支持和协助。"},{"i":27,"n":"第二十七条","txt":"公安机关应当建立完善打击治理电信网络诈骗工作机制，加强专门队伍和专业技术建设，各警种、各地公安机关应当密切配合，依法有效惩处电信网络诈骗活动。"},{"i":28,"n":"第二十八条","txt":"金融、电信、网信部门依照职责对银行业金融机构、非银行支付机构、电信业务经营者、互联网服务提供者落实本法规定情况进行监督检查。有关监督检查活动应当依法规范开展。"},{"i":29,"n":"第二十九条","txt":"个人信息处理者应当依照《中华人民共和国个人信息保护法》等法律规定，规范个人信息处理，加强个人信息保护，建立个人信息被用于电信网络诈骗的防范机制。"},{"i":30,"n":"第三十条","txt":"电信业务经营者、银行业金融机构、非银行支付机构、互联网服务提供者应当对从业人员和用户开展反电信网络诈骗宣传，在有关业务活动中对防范电信网络诈骗作出提示，对本领域新出现的电信网络诈骗手段及时向用户作出提醒，对非法买卖、出租、出借本人有关卡、账户、账号等被用于电信网络诈骗的法律责任作出警示。"},{"i":31,"n":"第三十一条","txt":"任何单位和个人不得非法买卖、出租、出借电话卡、物联网卡、电信线路、短信端口、银行账户、支付账户、互联网账号等，不得提供实名核验帮助；不得假冒他人身份或者虚构代理关系开立上述卡、账户、账号等。"},{"i":32,"n":"第三十二条","txt":"国家支持电信业务经营者、银行业金融机构、非银行支付机构、互联网服务提供者研究开发有关电信网络诈骗反制技术，用于监测识别、动态封堵和处置涉诈异常信息、活动。"},{"i":33,"n":"第三十三条","txt":"国家推进网络身份认证公共服务建设，支持个人、企业自愿使用，电信业务经营者、银行业金融机构、非银行支付机构、互联网服务提供者对存在涉诈异常的电话卡、银行账户、支付账户、互联网账号，可以通过国家网络身份认证公共服务对用户身份重新进行核验。"},{"i":34,"n":"第三十四条","txt":"公安机关应当会同金融、电信、网信部门组织银行业金融机构、非银行支付机构、电信业务经营者、互联网服务提供者等建立预警劝阻系统，对预警发现的潜在被害人，根据情况及时采取相应劝阻措施。对电信网络诈骗案件应当加强追赃挽损，完善涉案资金处置制度，及时返还被害人的合法财产。对遭受重大生活困难的被害人，符合国家有关救助条件的，有关方面依照规定给予救助。"},{"i":35,"n":"第三十五条","txt":"经国务院反电信网络诈骗工作机制决定或者批准，公安、金融、电信等部门对电信网络诈骗活动严重的特定地区，可以依照国家有关规定采取必要的临时风险防范措施。"},{"i":36,"n":"第三十六条","txt":"对前往电信网络诈骗活动严重地区的人员，出境活动存在重大涉电信网络诈骗活动嫌疑的，移民管理机构可以决定不准其出境。"},{"i":37,"n":"第三十七条","txt":"国务院公安部门等会同外交部门加强国际执法司法合作，与有关国家、地区、国际组织建立有效合作机制，通过开展国际警务合作等方式，提升在信息交流、调查取证、侦查抓捕、追赃挽损等方面的合作水平，有效打击遏制跨境电信网络诈骗活动。"},{"i":38,"n":"第三十八条","txt":"组织、策划、实施、参与电信网络诈骗活动或者为电信网络诈骗活动提供帮助，构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"电信业务经营者违反本法规定，有下列情形之一的，由有关主管部门责令改正，情节较轻的，给予警告、通报批评，或者处五万元以上五十万元以下罚款；情节严重的，处五十万元以上五百万元以下罚款，并可以由有关主管部门责令暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照，对其直接负责的主管人员和其他直接责任人员，处一万元以上二十万元以下罚款："},{"i":40,"n":"第四十条","txt":"银行业金融机构、非银行支付机构违反本法规定，有下列情形之一的，由有关主管部门责令改正，情节较轻的，给予警告、通报批评，或者处五万元以上五十万元以下罚款；情节严重的，处五十万元以上五百万元以下罚款，并可以由有关主管部门责令停止新增业务、缩减业务类型或者业务范围、暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照，对其直接负责的主管人员和其他直接责任人员，处一万元以上二十万元以下罚款："},{"i":41,"n":"第四十一条","txt":"电信业务经营者、互联网服务提供者违反本法规定，有下列情形之一的，由有关主管部门责令改正，情节较轻的，给予警告、通报批评，或者处五万元以上五十万元以下罚款；情节严重的，处五十万元以上五百万元以下罚款，并可以由有关主管部门责令暂停相关业务、停业整顿、关闭网站或者应用程序、吊销相关业务许可证或者吊销营业执照，对其直接负责的主管人员和其他直接责任人员，处一万元以上二十万元以下罚款："},{"i":42,"n":"第四十二条","txt":"违反本法第十四条、第二十五条第一款规定的，没收违法所得，由公安机关或者有关主管部门处违法所得一倍以上十倍以下罚款，没有违法所得或者违法所得不足五万元的，处五十万元以下罚款；情节严重的，由公安机关并处十五日以下拘留。"},{"i":43,"n":"第四十三条","txt":"违反本法第二十五条第二款规定，由有关主管部门责令改正，情节较轻的，给予警告、通报批评，或者处五万元以上五十万元以下罚款；情节严重的，处五十万元以上五百万元以下罚款，并可以由有关主管部门责令暂停相关业务、停业整顿、关闭网站或者应用程序，对其直接负责的主管人员和其他直接责任人员，处一万元以上二十万元以下罚款。"},{"i":44,"n":"第四十四条","txt":"违反本法第三十一条第一款规定的，没收违法所得，由公安机关处违法所得一倍以上十倍以下罚款，没有违法所得或者违法所得不足二万元的，处二十万元以下罚款；情节严重的，并处十五日以下拘留。"},{"i":45,"n":"第四十五条","txt":"反电信网络诈骗工作有关部门、单位的工作人员滥用职权、玩忽职守、徇私舞弊，或者有其他违反本法规定行为，构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"组织、策划、实施、参与电信网络诈骗活动或者为电信网络诈骗活动提供相关帮助的违法犯罪人员，除依法承担刑事责任、行政责任以外，造成他人损害的，依照《中华人民共和国民法典》等法律的规定承担民事责任。"},{"i":47,"n":"第四十七条","txt":"人民检察院在履行反电信网络诈骗职责中，对于侵害国家利益和社会公共利益的行为，可以依法向人民法院提起公益诉讼。"},{"i":48,"n":"第四十八条","txt":"有关单位和个人对依照本法作出的行政处罚和行政强制措施决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":49,"n":"第四十九条","txt":"反电信网络诈骗工作涉及的有关管理和责任制度，本法没有规定的，适用《中华人民共和国网络安全法》、《中华人民共和国个人信息保护法》、《中华人民共和国反洗钱法》等相关法律规定。"},{"i":50,"n":"第五十条","txt":"本法自2022年12月1日起施行。"}],"fanjiandiefa":[{"i":1,"n":"第一条","txt":"为了加强反间谍工作，防范、制止和惩治间谍行为，维护国家安全，保护人民利益，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"反间谍工作坚持党中央集中统一领导，坚持总体国家安全观，坚持公开工作与秘密工作相结合、专门工作与群众路线相结合，坚持积极防御、依法惩治、标本兼治，筑牢国家安全人民防线。"},{"i":3,"n":"第三条","txt":"反间谍工作应当依法进行，尊重和保障人权，保障个人和组织的合法权益。"},{"i":4,"n":"第四条","txt":"本法所称间谍行为，是指下列行为："},{"i":5,"n":"第五条","txt":"国家建立反间谍工作协调机制，统筹协调反间谍工作中的重大事项，研究、解决反间谍工作中的重大问题。"},{"i":6,"n":"第六条","txt":"国家安全机关是反间谍工作的主管机关。"},{"i":7,"n":"第七条","txt":"中华人民共和国公民有维护国家的安全、荣誉和利益的义务，不得有危害国家的安全、荣誉和利益的行为。"},{"i":8,"n":"第八条","txt":"任何公民和组织都应当依法支持、协助反间谍工作，保守所知悉的国家秘密和反间谍工作秘密。"},{"i":9,"n":"第九条","txt":"国家对支持、协助反间谍工作的个人和组织给予保护。"},{"i":10,"n":"第十条","txt":"境外机构、组织、个人实施或者指使、资助他人实施的，或者境内机构、组织、个人与境外机构、组织、个人相勾结实施的危害中华人民共和国国家安全的间谍行为，都必须受到法律追究。"},{"i":11,"n":"第十一条","txt":"国家安全机关及其工作人员在工作中，应当严格依法办事，不得超越职权、滥用职权，不得侵犯个人和组织的合法权益。"},{"i":12,"n":"第十二条","txt":"国家机关、人民团体、企业事业组织和其他社会组织承担本单位反间谍安全防范工作的主体责任，落实反间谍安全防范措施，对本单位的人员进行维护国家安全的教育，动员、组织本单位的人员防范、制止间谍行为。"},{"i":13,"n":"第十三条","txt":"各级人民政府和有关部门应当组织开展反间谍安全防范宣传教育，将反间谍安全防范知识纳入教育、培训、普法宣传内容，增强全民反间谍安全防范意识和国家安全素养。"},{"i":14,"n":"第十四条","txt":"任何个人和组织都不得非法获取、持有属于国家秘密的文件、数据、资料、物品。"},{"i":15,"n":"第十五条","txt":"任何个人和组织都不得非法生产、销售、持有、使用间谍活动特殊需要的专用间谍器材。专用间谍器材由国务院国家安全主管部门依照国家有关规定确认。"},{"i":16,"n":"第十六条","txt":"任何公民和组织发现间谍行为，应当及时向国家安全机关举报；向公安机关等其他国家机关、组织举报的，相关国家机关、组织应当立即移送国家安全机关处理。"},{"i":17,"n":"第十七条","txt":"国家建立反间谍安全防范重点单位管理制度。"},{"i":18,"n":"第十八条","txt":"反间谍安全防范重点单位应当加强对工作人员反间谍安全防范的教育和管理，对离岗离职人员脱密期内履行反间谍安全防范义务的情况进行监督检查。"},{"i":19,"n":"第十九条","txt":"反间谍安全防范重点单位应当加强对涉密事项、场所、载体等的日常安全防范管理，采取隔离加固、封闭管理、设置警戒等反间谍物理防范措施。"},{"i":20,"n":"第二十条","txt":"反间谍安全防范重点单位应当按照反间谍技术防范的要求和标准，采取相应的技术措施和其他必要措施，加强对要害部门部位、网络设施、信息系统的反间谍技术防范。"},{"i":21,"n":"第二十一条","txt":"在重要国家机关、国防军工单位和其他重要涉密单位以及重要军事设施的周边安全控制区域内新建、改建、扩建建设项目的，由国家安全机关实施涉及国家安全事项的建设项目许可。"},{"i":22,"n":"第二十二条","txt":"国家安全机关根据反间谍工作需要，可以会同有关部门制定反间谍技术防范标准，指导有关单位落实反间谍技术防范措施，对存在隐患的单位，经过严格的批准手续，可以进行反间谍技术防范检查和检测。"},{"i":23,"n":"第二十三条","txt":"国家安全机关在反间谍工作中依法行使本法和有关法律规定的职权。"},{"i":24,"n":"第二十四条","txt":"国家安全机关工作人员依法执行反间谍工作任务时，依照规定出示工作证件，可以查验中国公民或者境外人员的身份证明，向有关个人和组织问询有关情况，对身份不明、有间谍行为嫌疑的人员，可以查看其随带物品。"},{"i":25,"n":"第二十五条","txt":"国家安全机关工作人员依法执行反间谍工作任务时，经设区的市级以上国家安全机关负责人批准，出示工作证件，可以查验有关个人和组织的电子设备、设施及有关程序、工具。查验中发现存在危害国家安全情形的，国家安全机关应当责令其采取措施立即整改。拒绝整改或者整改后仍存在危害国家安全隐患的，可以予以查封、扣押。"},{"i":26,"n":"第二十六条","txt":"国家安全机关工作人员依法执行反间谍工作任务时，根据国家有关规定，经设区的市级以上国家安全机关负责人批准，可以查阅、调取有关的文件、数据、资料、物品，有关个人和组织应当予以配合。查阅、调取不得超出执行反间谍工作任务所需的范围和限度。"},{"i":27,"n":"第二十七条","txt":"需要传唤违反本法的人员接受调查的，经国家安全机关办案部门负责人批准，使用传唤证传唤。对现场发现的违反本法的人员，国家安全机关工作人员依照规定出示工作证件，可以口头传唤，但应当在询问笔录中注明。传唤的原因和依据应当告知被传唤人。对无正当理由拒不接受传唤或者逃避传唤的人，可以强制传唤。"},{"i":28,"n":"第二十八条","txt":"国家安全机关调查间谍行为，经设区的市级以上国家安全机关负责人批准，可以依法对涉嫌间谍行为的人身、物品、场所进行检查。"},{"i":29,"n":"第二十九条","txt":"国家安全机关调查间谍行为，经设区的市级以上国家安全机关负责人批准，可以查询涉嫌间谍行为人员的相关财产信息。"},{"i":30,"n":"第三十条","txt":"国家安全机关调查间谍行为，经设区的市级以上国家安全机关负责人批准，可以对涉嫌用于间谍行为的场所、设施或者财物依法查封、扣押、冻结；不得查封、扣押、冻结与被调查的间谍行为无关的场所、设施或者财物。"},{"i":31,"n":"第三十一条","txt":"国家安全机关工作人员在反间谍工作中采取查阅、调取、传唤、检查、查询、查封、扣押、冻结等措施，应当由二人以上进行，依照有关规定出示工作证件及相关法律文书，并由相关人员在有关笔录等书面材料上签名、盖章。"},{"i":32,"n":"第三十二条","txt":"在国家安全机关调查了解有关间谍行为的情况、收集有关证据时，有关个人和组织应当如实提供，不得拒绝。"},{"i":33,"n":"第三十三条","txt":"对出境后可能对国家安全造成危害，或者对国家利益造成重大损失的中国公民，国务院国家安全主管部门可以决定其在一定期限内不准出境，并通知移民管理机构。"},{"i":34,"n":"第三十四条","txt":"对入境后可能进行危害中华人民共和国国家安全活动的境外人员，国务院国家安全主管部门可以通知移民管理机构不准其入境。"},{"i":35,"n":"第三十五条","txt":"对国家安全机关通知不准出境或者不准入境的人员，移民管理机构应当按照国家有关规定执行；不准出境、入境情形消失的，国家安全机关应当及时撤销不准出境、入境决定，并通知移民管理机构。"},{"i":36,"n":"第三十六条","txt":"国家安全机关发现涉及间谍行为的网络信息内容或者网络攻击等风险，应当依照《中华人民共和国网络安全法》规定的职责分工，及时通报有关部门，由其依法处置或者责令电信业务经营者、互联网服务提供者及时采取修复漏洞、加固网络防护、停止传输、消除程序和内容、暂停相关服务、下架相关应用、关闭相关网站等措施，保存相关记录。情况紧急，不立即采取措施将对国家安全造成严重危害的，由国家安全机关责令有关单位修复漏洞、停止相关传输、暂停相关服务，并通报有关部门。"},{"i":37,"n":"第三十七条","txt":"国家安全机关因反间谍工作需要，根据国家有关规定，经过严格的批准手续，可以采取技术侦察措施和身份保护措施。"},{"i":38,"n":"第三十八条","txt":"对违反本法规定，涉嫌犯罪，需要对有关事项是否属于国家秘密或者情报进行鉴定以及需要对危害后果进行评估的，由国家保密部门或者省、自治区、直辖市保密部门按照程序在一定期限内进行鉴定和组织评估。"},{"i":39,"n":"第三十九条","txt":"国家安全机关经调查，发现间谍行为涉嫌犯罪的，应当依照《中华人民共和国刑事诉讼法》的规定立案侦查。"},{"i":40,"n":"第四十条","txt":"国家安全机关工作人员依法履行职责，受法律保护。"},{"i":41,"n":"第四十一条","txt":"国家安全机关依法调查间谍行为，邮政、快递等物流运营单位和电信业务经营者、互联网服务提供者应当提供必要的支持和协助。"},{"i":42,"n":"第四十二条","txt":"国家安全机关工作人员因执行紧急任务需要，经出示工作证件，享有优先乘坐公共交通工具、优先通行等通行便利。"},{"i":43,"n":"第四十三条","txt":"国家安全机关工作人员依法执行任务时，依照规定出示工作证件，可以进入有关场所、单位；根据国家有关规定，经过批准，出示工作证件，可以进入限制进入的有关地区、场所、单位。"},{"i":44,"n":"第四十四条","txt":"国家安全机关因反间谍工作需要，根据国家有关规定，可以优先使用或者依法征用国家机关、人民团体、企业事业组织和其他社会组织以及个人的交通工具、通信工具、场地和建筑物等，必要时可以设置相关工作场所和设施设备，任务完成后应当及时归还或者恢复原状，并依照规定支付相应费用；造成损失的，应当给予补偿。"},{"i":45,"n":"第四十五条","txt":"国家安全机关因反间谍工作需要，根据国家有关规定，可以提请海关、移民管理等检查机关对有关人员提供通关便利，对有关资料、器材等予以免检。有关检查机关应当依法予以协助。"},{"i":46,"n":"第四十六条","txt":"国家安全机关工作人员因执行任务，或者个人因协助执行反间谍工作任务，本人或者其近亲属的人身安全受到威胁时，国家安全机关应当会同有关部门依法采取必要措施，予以保护、营救。"},{"i":47,"n":"第四十七条","txt":"对为反间谍工作做出贡献并需要安置的人员，国家给予妥善安置。"},{"i":48,"n":"第四十八条","txt":"对因开展反间谍工作或者支持、协助反间谍工作导致伤残或者牺牲、死亡的人员，根据国家有关规定给予相应的抚恤优待。"},{"i":49,"n":"第四十九条","txt":"国家鼓励反间谍领域科技创新，发挥科技在反间谍工作中的作用。"},{"i":50,"n":"第五十条","txt":"国家安全机关应当加强反间谍专业力量人才队伍建设和专业训练，提升反间谍工作能力。"},{"i":51,"n":"第五十一条","txt":"国家安全机关应当严格执行内部监督和安全审查制度，对其工作人员遵守法律和纪律等情况进行监督，并依法采取必要措施，定期或者不定期进行安全审查。"},{"i":52,"n":"第五十二条","txt":"任何个人和组织对国家安全机关及其工作人员超越职权、滥用职权和其他违法行为，都有权向上级国家安全机关或者监察机关、人民检察院等有关部门检举、控告。受理检举、控告的国家安全机关或者监察机关、人民检察院等有关部门应当及时查清事实，依法处理，并将处理结果及时告知检举人、控告人。"},{"i":53,"n":"第五十三条","txt":"实施间谍行为，构成犯罪的，依法追究刑事责任。"},{"i":54,"n":"第五十四条","txt":"个人实施间谍行为，尚不构成犯罪的，由国家安全机关予以警告或者处十五日以下行政拘留，单处或者并处五万元以下罚款，违法所得在五万元以上的，单处或者并处违法所得一倍以上五倍以下罚款，并可以由有关部门依法予以处分。"},{"i":55,"n":"第五十五条","txt":"实施间谍行为，有自首或者立功表现的，可以从轻、减轻或者免除处罚；有重大立功表现的，给予奖励。"},{"i":56,"n":"第五十六条","txt":"国家机关、人民团体、企业事业组织和其他社会组织未按照本法规定履行反间谍安全防范义务的，国家安全机关可以责令改正；未按照要求改正的，国家安全机关可以约谈相关负责人，必要时可以将约谈情况通报该单位上级主管部门；产生危害后果或者不良影响的，国家安全机关可以予以警告、通报批评；情节严重的，对负有责任的领导人员和直接责任人员，由有关部门依法予以处分。"},{"i":57,"n":"第五十七条","txt":"违反本法第二十一条规定新建、改建、扩建建设项目的，由国家安全机关责令改正，予以警告；拒不改正或者情节严重的，责令停止建设或者使用、暂扣或者吊销许可证件，或者建议有关主管部门依法予以处理。"},{"i":58,"n":"第五十八条","txt":"违反本法第四十一条规定的，由国家安全机关责令改正，予以警告或者通报批评；拒不改正或者情节严重的，由有关主管部门依照相关法律法规予以处罚。"},{"i":59,"n":"第五十九条","txt":"违反本法规定，拒不配合数据调取的，由国家安全机关依照《中华人民共和国数据安全法》的有关规定予以处罚。"},{"i":60,"n":"第六十条","txt":"违反本法规定，有下列行为之一，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由国家安全机关予以警告或者处十日以下行政拘留，可以并处三万元以下罚款："},{"i":61,"n":"第六十一条","txt":"非法获取、持有属于国家秘密的文件、数据、资料、物品，以及非法生产、销售、持有、使用专用间谍器材，尚不构成犯罪的，由国家安全机关予以警告或者处十日以下行政拘留。"},{"i":62,"n":"第六十二条","txt":"国家安全机关对依照本法查封、扣押、冻结的财物，应当妥善保管，并按照下列情形分别处理："},{"i":63,"n":"第六十三条","txt":"涉案财物符合下列情形之一的，应当依法予以追缴、没收，或者采取措施消除隐患："},{"i":64,"n":"第六十四条","txt":"行为人及其近亲属或者其他相关人员，因行为人实施间谍行为从间谍组织及其代理人获取的所有利益，由国家安全机关依法采取追缴、没收等措施。"},{"i":65,"n":"第六十五条","txt":"国家安全机关依法收缴的罚款以及没收的财物，一律上缴国库。"},{"i":66,"n":"第六十六条","txt":"境外人员违反本法的，国务院国家安全主管部门可以决定限期出境，并决定其不准入境的期限。未在规定期限内离境的，可以遣送出境。"},{"i":67,"n":"第六十七条","txt":"国家安全机关作出行政处罚决定之前，应当告知当事人拟作出的行政处罚内容及事实、理由、依据，以及当事人依法享有的陈述、申辩、要求听证等权利，并依照《中华人民共和国行政处罚法》的有关规定实施。"},{"i":68,"n":"第六十八条","txt":"当事人对行政处罚决定、行政强制措施决定、行政许可决定不服的，可以自收到决定书之日起六十日内，依法申请复议；对复议决定不服的，可以自收到复议决定书之日起十五日内，依法向人民法院提起诉讼。"},{"i":69,"n":"第六十九条","txt":"国家安全机关工作人员滥用职权、玩忽职守、徇私舞弊，或者有非法拘禁、刑讯逼供、暴力取证、违反规定泄露国家秘密、工作秘密、商业秘密和个人隐私、个人信息等行为，依法予以处分，构成犯罪的，依法追究刑事责任。"},{"i":70,"n":"第七十条","txt":"国家安全机关依照法律、行政法规和国家有关规定，履行防范、制止和惩治间谍行为以外的危害国家安全行为的职责，适用本法的有关规定。"},{"i":71,"n":"第七十一条","txt":"本法自2023年7月1日起施行。"}],"quanguorenmindaibiaodahuichangwuweiyuanhuiguanyuchecf1c1":[]};
